struct CachedPostgresClient {
    cache_key: String,
    client: Option<tokio_postgres::Client>,
    cache: Arc<Mutex<HashMap<String, Vec<tokio_postgres::Client>>>>,
}

fn prune_postgres_connection_cache(
    cached_connections: &mut HashMap<String, Vec<tokio_postgres::Client>>,
) {
    cached_connections.retain(|_, clients| {
        clients.retain(|client| !client.is_closed());
        if clients.len() > POSTGRES_IDLE_CONNECTION_CACHE_MAX_PER_KEY {
            clients.truncate(POSTGRES_IDLE_CONNECTION_CACHE_MAX_PER_KEY);
        }
        !clients.is_empty()
    });

    let mut total_idle = cached_connections.values().map(Vec::len).sum::<usize>();
    if total_idle <= POSTGRES_IDLE_CONNECTION_CACHE_MAX_TOTAL {
        return;
    }

    let keys = cached_connections.keys().cloned().collect::<Vec<_>>();
    for key in keys {
        if total_idle <= POSTGRES_IDLE_CONNECTION_CACHE_MAX_TOTAL {
            break;
        }
        let Some(clients) = cached_connections.get_mut(&key) else {
            continue;
        };
        while total_idle > POSTGRES_IDLE_CONNECTION_CACHE_MAX_TOTAL && clients.pop().is_some() {
            total_idle -= 1;
        }
    }
    cached_connections.retain(|_, clients| !clients.is_empty());
}

impl PostgresConnectionLease {
    fn abort(self) {}
}

impl std::ops::Deref for CachedPostgresClient {
    type Target = tokio_postgres::Client;

    fn deref(&self) -> &Self::Target {
        self.client
            .as_ref()
            .expect("cached postgres client missing inner client")
    }
}

impl std::ops::DerefMut for CachedPostgresClient {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.client
            .as_mut()
            .expect("cached postgres client missing inner client")
    }
}

impl Drop for CachedPostgresClient {
    fn drop(&mut self) {
        if let Some(client) = self.client.take() {
            if client.is_closed() {
                return;
            }
            let mut cached_connections = self.cache.lock().unwrap();
            let clients = cached_connections
                .entry(self.cache_key.clone())
                .or_default();
            if clients.len() < POSTGRES_IDLE_CONNECTION_CACHE_MAX_PER_KEY {
                clients.push(client);
            }
            prune_postgres_connection_cache(&mut cached_connections);
        }
    }
}

fn kanqual_data_dir(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    if let Some(smoke_data_dir) = smoke_test_data_dir_override() {
        fs::create_dir_all(&smoke_data_dir).map_err(|e| e.to_string())?;
        return Ok(smoke_data_dir);
    }
    if let Some(portable_dir) = portable_data_dir()? {
        fs::create_dir_all(&portable_dir).map_err(|e| e.to_string())?;
        return Ok(portable_dir);
    }
    let base = app.path().app_data_dir().map_err(|e| e.to_string())?;
    if cfg!(debug_assertions) {
        Ok(base.join(DEV_DATA_DIR_NAME))
    } else {
        Ok(base)
    }
}

fn executable_dir() -> Result<PathBuf, String> {
    let exe_path = std::env::current_exe().map_err(|e| e.to_string())?;
    exe_path
        .parent()
        .map(Path::to_path_buf)
        .ok_or_else(|| "Could not resolve executable directory.".to_string())
}

fn portable_data_dir() -> Result<Option<PathBuf>, String> {
    let exe_dir = executable_dir()?;
    if exe_dir.join(PORTABLE_MODE_MARKER_FILE).exists() {
        return Ok(Some(exe_dir.join(PORTABLE_DATA_DIR_NAME)));
    }
    Ok(None)
}

fn smoke_test_env_var(name: &str) -> Option<String> {
    std::env::var(name)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn smoke_test_enabled() -> bool {
    smoke_test_env_var("KANQUAL_SMOKE_TEST")
        .map(|value| {
            matches!(
                value.to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(false)
}

fn smoke_test_data_dir_override() -> Option<PathBuf> {
    if !smoke_test_enabled() {
        return None;
    }
    smoke_test_env_var("KANQUAL_SMOKE_DATA_DIR").map(PathBuf::from)
}

fn smoke_test_state_path() -> Option<PathBuf> {
    if !smoke_test_enabled() {
        return None;
    }
    smoke_test_env_var("KANQUAL_SMOKE_STATE_PATH").map(PathBuf::from)
}

fn write_smoke_test_state(
    _app: &tauri::AppHandle,
    payload: serde_json::Value,
) -> Result<(), String> {
    let Some(state_path) = smoke_test_state_path() else {
        return Ok(());
    };

    if let Some(parent) = state_path.parent() {
        fs::create_dir_all(parent).map_err(|e| e.to_string())?;
    }

    let serialized = serde_json::to_string_pretty(&payload).map_err(|e| e.to_string())?;
    let temp_path = state_path.with_extension(format!(
        "{}.tmp",
        state_path
            .extension()
            .and_then(|value| value.to_str())
            .unwrap_or("json")
    ));
    fs::write(&temp_path, serialized).map_err(|e| e.to_string())?;
    if state_path.exists() {
        fs::remove_file(&state_path).map_err(|e| e.to_string())?;
    }
    fs::rename(&temp_path, &state_path).map_err(|e| e.to_string())?;
    Ok(())
}

fn is_portable_mode() -> Result<bool, String> {
    Ok(portable_data_dir()?.is_some())
}

fn webview_data_dir(app: &tauri::AppHandle, label: &str) -> Result<PathBuf, String> {
    Ok(kanqual_data_dir(app)?.join("webview").join(label))
}

fn create_configured_window(app: &mut tauri::App, label: &str) -> Result<(), String> {
    let window_config = app
        .config()
        .app
        .windows
        .iter()
        .find(|window| window.label == label)
        .ok_or_else(|| format!("Could not find window config for label `{label}`."))?;

    let data_dir = webview_data_dir(&app.app_handle(), label)?;
    fs::create_dir_all(&data_dir).map_err(|e| e.to_string())?;

    WebviewWindowBuilder::from_config(app.handle(), window_config)
        .map_err(|e| e.to_string())?
        .data_directory(data_dir)
        .build()
        .map_err(|e| e.to_string())?;

    Ok(())
}

fn current_time_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

fn postgres_auth_throttle_key(auth_kind: &str, username: &str, origin: &str) -> String {
    format!(
        "{}:{}:{}",
        auth_kind.trim().to_lowercase(),
        username.trim().to_lowercase(),
        origin.trim().to_lowercase()
    )
}

fn check_postgres_auth_throttle(
    throttle_state: &PostgresExperimentAuthThrottleState,
    auth_kind: &str,
    username: &str,
    origin: &str,
) -> Result<(), String> {
    let now = current_time_ms();
    let key = postgres_auth_throttle_key(auth_kind, username, origin);
    let mut attempts_by_key = throttle_state.0.lock().unwrap();
    let attempts = attempts_by_key.entry(key).or_default();
    attempts
        .retain(|attempt_at| now.saturating_sub(*attempt_at) <= POSTGRES_AUTH_THROTTLE_WINDOW_MS);
    if attempts.len() >= POSTGRES_AUTH_THROTTLE_MAX_FAILURES {
        let oldest_attempt = attempts.iter().copied().min().unwrap_or(now);
        let wait_ms = oldest_attempt
            .saturating_add(POSTGRES_AUTH_THROTTLE_WINDOW_MS)
            .saturating_sub(now);
        let wait_seconds = wait_ms.div_ceil(1000).max(1);
        return Err(format!(
            "Too many failed sign-in attempts. Try again in about {wait_seconds} seconds."
        ));
    }
    Ok(())
}

fn record_postgres_auth_failure(
    throttle_state: &PostgresExperimentAuthThrottleState,
    auth_kind: &str,
    username: &str,
    origin: &str,
) {
    let now = current_time_ms();
    let key = postgres_auth_throttle_key(auth_kind, username, origin);
    let mut attempts_by_key = throttle_state.0.lock().unwrap();
    let attempts = attempts_by_key.entry(key).or_default();
    attempts
        .retain(|attempt_at| now.saturating_sub(*attempt_at) <= POSTGRES_AUTH_THROTTLE_WINDOW_MS);
    attempts.push(now);
}

fn clear_postgres_auth_failures(
    throttle_state: &PostgresExperimentAuthThrottleState,
    auth_kind: &str,
    username: &str,
    origin: &str,
) {
    let key = postgres_auth_throttle_key(auth_kind, username, origin);
    throttle_state.0.lock().unwrap().remove(&key);
}

