fn postgres_auth_kind_for_username(app: &tauri::AppHandle, username: &str) -> Option<String> {
    let normalized = username.trim().to_lowercase();
    if normalized.is_empty() {
        return None;
    }
    let identity = load_or_create_postgres_bootstrap_identity(app).ok()?;
    if identity
        .superuser_name
        .trim()
        .eq_ignore_ascii_case(&normalized)
    {
        Some("postgres_admin".to_string())
    } else {
        Some("app_user".to_string())
    }
}

fn days_from_civil(year: i32, month: u32, day: u32) -> i64 {
    let year = year - if month <= 2 { 1 } else { 0 };
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let yoe = year - era * 400;
    let month = month as i32;
    let day = day as i32;
    let doy = (153 * (month + if month > 2 { -3 } else { 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    (era * 146097 + doe - 719468) as i64
}

fn parse_postgres_log_timestamp_ms(line: &str) -> Option<u64> {
    let bytes = line.as_bytes();
    if bytes.len() < 19
        || bytes.get(4) != Some(&b'-')
        || bytes.get(7) != Some(&b'-')
        || bytes.get(10) != Some(&b' ')
        || bytes.get(13) != Some(&b':')
        || bytes.get(16) != Some(&b':')
    {
        return None;
    }
    let year = line.get(0..4)?.parse::<i32>().ok()?;
    let month = line.get(5..7)?.parse::<u32>().ok()?;
    let day = line.get(8..10)?.parse::<u32>().ok()?;
    let hour = line.get(11..13)?.parse::<u64>().ok()?;
    let minute = line.get(14..16)?.parse::<u64>().ok()?;
    let second = line.get(17..19)?.parse::<u64>().ok()?;
    let mut millisecond = 0_u64;
    if line.get(19..20) == Some(".") {
        let fraction = line
            .get(20..)
            .unwrap_or("")
            .chars()
            .take_while(|character| character.is_ascii_digit())
            .take(3)
            .collect::<String>();
        if !fraction.is_empty() {
            millisecond = format!("{fraction:0<3}").parse::<u64>().ok()?;
        }
    }
    let days = days_from_civil(year, month, day);
    if days < 0 {
        return None;
    }
    Some(
        days as u64 * 86_400_000
            + hour * 3_600_000
            + minute * 60_000
            + second * 1_000
            + millisecond,
    )
}

fn extract_quoted_after(input: &str, marker: &str) -> Option<String> {
    let start = input.find(marker)? + marker.len();
    let rest = input.get(start..)?;
    let end = rest.find('"')?;
    Some(rest.get(..end)?.to_string())
}

fn extract_postgres_log_key_value(input: &str, key: &str) -> Option<String> {
    let marker = format!("{key}=");
    let start = input.find(&marker)? + marker.len();
    let rest = input.get(start..)?.trim_start();
    if let Some(stripped) = rest.strip_prefix('"') {
        return stripped
            .find('"')
            .and_then(|end| stripped.get(..end).map(str::to_string));
    }
    let value = rest
        .split_whitespace()
        .next()
        .unwrap_or("")
        .trim_matches(',')
        .trim_matches('"')
        .to_string();
    if value.is_empty() {
        None
    } else {
        Some(value)
    }
}

fn parse_postgres_log_prefix_client_ip(line: &str) -> Option<String> {
    let before_level = line
        .split_once(" LOG: ")
        .map(|(prefix, _)| prefix)
        .or_else(|| line.split_once(" FATAL: ").map(|(prefix, _)| prefix))?;
    let remote = before_level.split_whitespace().last()?.trim();
    if remote.is_empty() || remote == "[local]" {
        return Some("local".to_string());
    }
    let without_parenthesized_port = remote
        .split_once('(')
        .map(|(host, _)| host)
        .unwrap_or(remote);
    let host = without_parenthesized_port
        .rsplit_once(':')
        .map(|(host, _)| host)
        .unwrap_or(without_parenthesized_port);
    Some(host.trim_matches('[').trim_matches(']').to_string())
}

fn parse_postgres_server_auth_log_line(
    app: Option<&tauri::AppHandle>,
    id: String,
    line: &str,
) -> Option<PostgresExperimentAuthAuditEntry> {
    let timestamp_ms = parse_postgres_log_timestamp_ms(line)?;
    let client_ip_from_prefix = parse_postgres_log_prefix_client_ip(line);
    let mut event = String::new();
    let mut outcome = String::new();
    let mut message = String::new();
    let mut username = None;
    let mut database = None;
    let mut client_ip = client_ip_from_prefix;
    let mut reason = None;

    if line.contains(" LOG:  connection authorized:") {
        event = "postgres.server.auth.login".to_string();
        outcome = "success".to_string();
        message = "PostgreSQL connection authorized.".to_string();
        username = extract_postgres_log_key_value(line, "user");
        database = extract_postgres_log_key_value(line, "database");
    } else if line.contains(" LOG:  disconnection:") {
        event = "postgres.server.auth.logout".to_string();
        outcome = "success".to_string();
        message = "PostgreSQL connection closed.".to_string();
        username = extract_postgres_log_key_value(line, "user");
        database = extract_postgres_log_key_value(line, "database");
        if let Some(host) = extract_postgres_log_key_value(line, "host") {
            client_ip = Some(if host == "[local]" {
                "local".to_string()
            } else {
                host
            });
        }
    } else if line.contains(" FATAL: ") {
        event = "postgres.server.auth.login".to_string();
        outcome = "failed".to_string();
        message = "PostgreSQL connection rejected.".to_string();
        username = extract_quoted_after(line, "user \"")
            .or_else(|| extract_postgres_log_key_value(line, "user"));
        database = extract_quoted_after(line, "database \"")
            .or_else(|| extract_postgres_log_key_value(line, "database"));
        if let Some(host) = extract_quoted_after(line, "host \"") {
            client_ip = Some(if host == "[local]" {
                "local".to_string()
            } else {
                host
            });
        }
        reason = Some(if line.contains("password authentication failed") {
            "password_rejected".to_string()
        } else if line.contains("no pg_hba.conf entry") {
            "pg_hba_rejected".to_string()
        } else {
            "auth_failed".to_string()
        });
    }

    if event.is_empty() {
        return None;
    }

    let auth_kind = app.and_then(|app| {
        username
            .as_deref()
            .and_then(|value| postgres_auth_kind_for_username(app, value))
    });
    let details = serde_json::json!({
        "source": "postgresql_server_log",
        "database": database,
        "raw": line,
    });
    Some(PostgresExperimentAuthAuditEntry {
        id,
        timestamp_ms,
        event,
        outcome,
        message,
        auth_kind,
        user_id: None,
        username,
        client_ip,
        role: None,
        reason,
        details_json: serde_json::to_string(&details).ok(),
    })
}

fn read_postgres_server_auth_audit_entries(
    app: &tauri::AppHandle,
) -> Vec<PostgresExperimentAuthAuditEntry> {
    let Ok(paths) = bundled_postgres::resolve_paths(app) else {
        return Vec::new();
    };
    let Ok(read_dir) = fs::read_dir(&paths.logs_dir) else {
        return Vec::new();
    };
    let mut log_paths: Vec<PathBuf> = read_dir
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| {
            path.is_file()
                && path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .map(|name| name.starts_with("postgresql-") && name.ends_with(".log"))
                    .unwrap_or(false)
        })
        .collect();
    log_paths.sort();
    if log_paths.len() > 30 {
        log_paths = log_paths.split_off(log_paths.len() - 30);
    }
    let mut entries = Vec::new();
    for path in log_paths {
        let Ok(contents) = fs::read_to_string(&path) else {
            continue;
        };
        let file_name = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("postgresql-log")
            .to_string();
        for (index, line) in contents.lines().enumerate() {
            let id = format!("postgres-server-auth-{file_name}-{index}");
            if let Some(entry) = parse_postgres_server_auth_log_line(Some(app), id, line.trim()) {
                entries.push(entry);
            }
        }
    }
    entries
}

fn kanqual_auth_diagnostics_entry_to_audit_entry(
    index: usize,
    parsed: serde_json::Value,
) -> Option<PostgresExperimentAuthAuditEntry> {
    let event = parsed
        .get("event")
        .and_then(|value| value.as_str())
        .unwrap_or("");
    let details = parsed
        .get("details")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let reason = details
        .get("reason")
        .and_then(|value| value.as_str())
        .unwrap_or("");
    let include = matches!(
        event,
        "postgres.auth.logout" | "postgres.auth.user_password_reset" | "postgres.auth.login_block"
    ) || (event == "postgres.auth.login"
        && matches!(
            reason,
            "missing_username"
                | "missing_password"
                | "username_contains_whitespace"
                | "rate_limited"
                | "account_blocked"
                | "account_disabled"
                | "database_unavailable"
        ));
    if !include {
        return None;
    }
    let details_json = serde_json::to_string(&details).ok();
    let username = details
        .get("username")
        .or_else(|| details.get("email"))
        .and_then(|value| value.as_str())
        .map(str::to_string);
    Some(PostgresExperimentAuthAuditEntry {
        id: format!("kanqual-auth-audit-{index}"),
        timestamp_ms: parsed
            .get("timestampMs")
            .and_then(|value| value.as_u64())
            .unwrap_or(0),
        event: event.to_string(),
        outcome: parsed
            .get("outcome")
            .and_then(|value| value.as_str())
            .unwrap_or("")
            .to_string(),
        message: parsed
            .get("message")
            .and_then(|value| value.as_str())
            .unwrap_or("")
            .to_string(),
        auth_kind: details
            .get("authKind")
            .and_then(|value| value.as_str())
            .map(str::to_string),
        user_id: details
            .get("userId")
            .and_then(|value| value.as_str())
            .map(str::to_string),
        username,
        client_ip: details
            .get("clientIp")
            .or_else(|| details.get("client_ip"))
            .or_else(|| details.get("ip"))
            .or_else(|| details.get("remoteAddress"))
            .or_else(|| details.get("remote_addr"))
            .and_then(|value| value.as_str())
            .map(str::to_string),
        role: details
            .get("role")
            .and_then(|value| value.as_str())
            .map(str::to_string),
        reason: details
            .get("reason")
            .and_then(|value| value.as_str())
            .map(str::to_string),
        details_json,
    })
}

fn read_kanqual_auth_diagnostics_audit_entries(
    app: &tauri::AppHandle,
) -> Vec<PostgresExperimentAuthAuditEntry> {
    read_postgres_auth_diagnostics_log(app)
        .into_iter()
        .filter_map(|(index, parsed)| kanqual_auth_diagnostics_entry_to_audit_entry(index, parsed))
        .collect()
}

fn read_combined_postgres_auth_audit_entries(
    app: &tauri::AppHandle,
) -> Vec<PostgresExperimentAuthAuditEntry> {
    let mut entries = read_postgres_server_auth_audit_entries(app);
    entries.extend(read_kanqual_auth_diagnostics_audit_entries(app));
    entries.sort_by(|a, b| {
        b.timestamp_ms
            .cmp(&a.timestamp_ms)
            .then_with(|| b.id.cmp(&a.id))
    });
    entries
}

fn active_postgres_auth_block_entry(
    app: &tauri::AppHandle,
    username: &str,
) -> Option<PostgresAuthBlockEntry> {
    let normalized_username = normalize_postgres_auth_block_username(username);
    if normalized_username.is_empty() {
        return None;
    }
    let now = current_time_ms();
    let entries = read_combined_postgres_auth_audit_entries(app);
    let mut reset_boundary_ms = 0_u64;
    let mut failed_attempts = Vec::new();

    for entry in entries {
        let timestamp_ms = entry.timestamp_ms;
        let event = entry.event.as_str();
        let outcome = entry.outcome.as_str();
        let auth_kind = entry.auth_kind.as_deref().unwrap_or("");
        let event_username = entry
            .username
            .as_deref()
            .map(normalize_postgres_auth_block_username)
            .unwrap_or_default();
        if event_username != normalized_username {
            continue;
        }
        let is_unblock_boundary = (event == "postgres.server.auth.login" && outcome == "success")
            || event == "postgres.auth.user_password_reset";
        if is_unblock_boundary && timestamp_ms > reset_boundary_ms {
            reset_boundary_ms = timestamp_ms;
        }
        let reason = entry.reason.as_deref().unwrap_or("");
        let is_failed_app_user_login = event == "postgres.server.auth.login"
            && outcome == "failed"
            && auth_kind == "app_user"
            && matches!(
                reason,
                "password_rejected" | "pg_hba_rejected" | "auth_failed"
            );
        if is_failed_app_user_login {
            failed_attempts.push(timestamp_ms);
        }
    }

    failed_attempts.retain(|attempt_at| *attempt_at > reset_boundary_ms);
    failed_attempts.sort_unstable();
    let failed_attempts_last_hour: Vec<u64> = failed_attempts
        .iter()
        .copied()
        .filter(|attempt_at| {
            now.saturating_sub(*attempt_at) <= POSTGRES_AUTH_PERMANENT_BLOCK_WINDOW_MS
        })
        .collect();
    let failed_attempts_last_five_minutes: Vec<u64> = failed_attempts
        .iter()
        .copied()
        .filter(|attempt_at| now.saturating_sub(*attempt_at) <= POSTGRES_AUTH_THROTTLE_WINDOW_MS)
        .collect();

    let mut permanently_blocked = false;
    for window_start_index in 0..failed_attempts.len() {
        let window_start = failed_attempts[window_start_index];
        let count = failed_attempts
            .iter()
            .skip(window_start_index)
            .take_while(|attempt_at| {
                attempt_at.saturating_sub(window_start) <= POSTGRES_AUTH_PERMANENT_BLOCK_WINDOW_MS
            })
            .count();
        if count >= POSTGRES_AUTH_PERMANENT_BLOCK_MAX_FAILURES {
            permanently_blocked = true;
            break;
        }
    }

    let blocked_until_ms = if !permanently_blocked
        && failed_attempts_last_five_minutes.len() >= POSTGRES_AUTH_THROTTLE_MAX_FAILURES
    {
        failed_attempts_last_five_minutes
            .iter()
            .min()
            .map(|oldest| oldest.saturating_add(POSTGRES_AUTH_THROTTLE_WINDOW_MS))
            .filter(|blocked_until| *blocked_until > now)
    } else {
        None
    };

    if !permanently_blocked && blocked_until_ms.is_none() && failed_attempts_last_hour.is_empty() {
        return None;
    }

    Some(PostgresAuthBlockEntry {
        failed_attempts_ms: failed_attempts_last_hour,
        blocked_until_ms,
        permanently_blocked,
    })
}

fn check_persistent_postgres_auth_block(
    app: &tauri::AppHandle,
    username: &str,
) -> Result<(), String> {
    let Some(entry) = active_postgres_auth_block_entry(app, username) else {
        return Ok(());
    };
    if entry.permanently_blocked {
        return Err(
            "This account is blocked after too many failed sign-in attempts. Ask the administrator to reset the password."
                .to_string(),
        );
    }
    if let Some(blocked_until) = entry.blocked_until_ms {
        let now = current_time_ms();
        if blocked_until > now {
            let wait_seconds = blocked_until.saturating_sub(now).div_ceil(1000).max(1);
            return Err(format!(
                "Too many failed sign-in attempts. Try again in about {wait_seconds} seconds."
            ));
        }
    }
    Ok(())
}

#[cfg(test)]
mod postgres_auth_regression_tests {
    use super::*;

    fn throttle_state() -> PostgresExperimentAuthThrottleState {
        PostgresExperimentAuthThrottleState(Mutex::new(HashMap::new()))
    }

    #[test]
    fn auth_throttle_keys_are_case_and_whitespace_insensitive() {
        assert_eq!(
            postgres_auth_throttle_key(" App_User ", " TestUser ", " LOCAL "),
            "app_user:testuser:local"
        );
    }

    #[test]
    fn auth_throttle_blocks_after_five_recent_failures() {
        let state = throttle_state();

        for _ in 0..POSTGRES_AUTH_THROTTLE_MAX_FAILURES {
            assert!(check_postgres_auth_throttle(&state, "app_user", "testuser", "local").is_ok());
            record_postgres_auth_failure(&state, "app_user", "testuser", "local");
        }

        let blocked = check_postgres_auth_throttle(&state, "app_user", "testuser", "local");
        assert!(blocked.is_err());
        assert!(blocked
            .unwrap_err()
            .contains("Too many failed sign-in attempts"));
    }

    #[test]
    fn auth_throttle_is_scoped_by_username_origin_and_auth_kind() {
        let state = throttle_state();

        for _ in 0..POSTGRES_AUTH_THROTTLE_MAX_FAILURES {
            record_postgres_auth_failure(&state, "app_user", "testuser", "local");
        }

        assert!(check_postgres_auth_throttle(&state, "app_user", "testuser", "local").is_err());
        assert!(check_postgres_auth_throttle(&state, "app_user", "otheruser", "local").is_ok());
        assert!(
            check_postgres_auth_throttle(&state, "app_user", "testuser", "192.168.1.25").is_ok()
        );
        assert!(
            check_postgres_auth_throttle(&state, "postgres_admin", "testuser", "local").is_ok()
        );
    }

    #[test]
    fn successful_login_can_clear_auth_throttle_failures() {
        let state = throttle_state();

        for _ in 0..POSTGRES_AUTH_THROTTLE_MAX_FAILURES {
            record_postgres_auth_failure(&state, "app_user", "testuser", "local");
        }
        assert!(check_postgres_auth_throttle(&state, "app_user", "testuser", "local").is_err());

        clear_postgres_auth_failures(&state, "app_user", "testuser", "local");
        assert!(check_postgres_auth_throttle(&state, "app_user", "testuser", "local").is_ok());
    }

    #[test]
    fn parses_postgres_authorized_connection_log_line() {
        let entry = parse_postgres_server_auth_log_line(
            None,
            "test-auth-success".to_string(),
            "2026-08-21 13:44:12.123 UTC [1234] testuser@kanqual 127.0.0.1(51234) LOG:  connection authorized: user=testuser database=kanqual application_name=kanqual",
        )
        .expect("expected auth log entry");

        assert_eq!(entry.event, "postgres.server.auth.login");
        assert_eq!(entry.outcome, "success");
        assert_eq!(entry.username.as_deref(), Some("testuser"));
        assert_eq!(entry.client_ip.as_deref(), Some("127.0.0.1"));
        assert_eq!(entry.timestamp_ms, 1_787_319_852_123);
    }

    #[test]
    fn parses_postgres_failed_password_log_line() {
        let entry = parse_postgres_server_auth_log_line(
            None,
            "test-auth-failure".to_string(),
            "2026-08-21 13:44:13.000 UTC [1235] @ 192.168.1.25(51235) FATAL:  password authentication failed for user \"testuser\"",
        )
        .expect("expected auth log entry");

        assert_eq!(entry.event, "postgres.server.auth.login");
        assert_eq!(entry.outcome, "failed");
        assert_eq!(entry.username.as_deref(), Some("testuser"));
        assert_eq!(entry.client_ip.as_deref(), Some("192.168.1.25"));
        assert_eq!(entry.reason.as_deref(), Some("password_rejected"));
    }

    #[test]
    fn login_failure_classifier_does_not_treat_bad_password_as_unavailable() {
        let psql_bad_password = "psql: error: connection to server at \"127.0.0.1\", port 5432 failed: FATAL:  password authentication failed for user \"kanqual_admin\"";
        assert!(!postgres_login_failure_is_runtime_unavailable(psql_bad_password));
    }

    #[test]
    fn login_failure_classifier_does_not_treat_wrapped_bad_password_as_unavailable() {
        let wrapped_bad_password = "Could not connect to PostgreSQL runtime: password authentication failed for user \"testuser\"";
        assert!(!postgres_login_failure_is_runtime_unavailable(wrapped_bad_password));
    }

    #[test]
    fn login_failure_classifier_treats_refused_connection_as_unavailable() {
        let refused = "psql: error: connection to server at \"127.0.0.1\", port 5432 failed: Connection refused";
        assert!(postgres_login_failure_is_runtime_unavailable(refused));
    }

    #[test]
    fn parses_postgres_disconnection_log_line() {
        let entry = parse_postgres_server_auth_log_line(
            None,
            "test-auth-disconnect".to_string(),
            "2026-08-21 13:44:14.000 UTC [1236] testuser@kanqual 127.0.0.1(51236) LOG:  disconnection: session time: 0:00:01.234 user=testuser database=kanqual host=127.0.0.1 port=51236",
        )
        .expect("expected auth log entry");

        assert_eq!(entry.event, "postgres.server.auth.logout");
        assert_eq!(entry.outcome, "success");
        assert_eq!(entry.username.as_deref(), Some("testuser"));
        assert_eq!(entry.client_ip.as_deref(), Some("127.0.0.1"));
    }
}

fn postgres_bootstrap_identity_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    Ok(kanqual_data_dir(app)?.join(POSTGRES_BOOTSTRAP_IDENTITY_FILE))
}

fn postgres_runtime_config_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    Ok(kanqual_data_dir(app)?.join(POSTGRES_RUNTIME_CONFIG_FILE))
}

fn generate_postgres_bootstrap_identity() -> PostgresBootstrapIdentity {
    let suffix = Alphanumeric
        .sample_string(&mut rand::rngs::OsRng, 24)
        .to_lowercase();
    PostgresBootstrapIdentity {
        version: 1,
        host: POSTGRES_DEFAULT_HOST.to_string(),
        port: POSTGRES_DEFAULT_PORT,
        superuser_name: format!("{POSTGRES_ADMIN_ROLE_PREFIX}{suffix}"),
        temporary_superuser_password: generate_temporary_password(),
        app_database: POSTGRES_DEFAULT_DATABASE.to_string(),
        bootstrap_applied: false,
        admin_handoff_completed: false,
        created_at_ms: current_time_ms(),
    }
}

fn postgres_runtime_config_from_identity(
    identity: &PostgresBootstrapIdentity,
) -> PostgresRuntimeConfig {
    PostgresRuntimeConfig {
        version: 1,
        network_mode: "device".to_string(),
        host: identity.host.clone(),
        port: identity.port,
        database: identity.app_database.clone(),
        user: String::new(),
        password: String::new(),
        ready: identity.bootstrap_applied,
        updated_at_ms: current_time_ms(),
    }
}

fn generate_identifier() -> String {
    uuid_like_token(36)
}

fn generate_temporary_password() -> String {
    format!("Kanqual-{}!", uuid_like_token(12))
}

fn uuid_like_token(len: usize) -> String {
    let alphabet = b"ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
    let mut bytes = vec![0_u8; len];
    rand::rngs::OsRng.fill_bytes(&mut bytes);
    bytes
        .into_iter()
        .map(|byte| alphabet[(byte as usize) % alphabet.len()] as char)
        .collect()
}

fn load_or_create_postgres_bootstrap_identity(
    app: &tauri::AppHandle,
) -> Result<PostgresBootstrapIdentity, String> {
    let data_dir = kanqual_data_dir(app)?;
    fs::create_dir_all(&data_dir).map_err(|e| e.to_string())?;
    let path = postgres_bootstrap_identity_path(app)?;
    if path.exists() {
        if let Ok(text) = fs::read_to_string(&path) {
            if let Ok(identity) = serde_json::from_str::<PostgresBootstrapIdentity>(&text) {
                if !identity.superuser_name.trim().is_empty()
                    && (identity.admin_handoff_completed
                        || !identity.temporary_superuser_password.trim().is_empty())
                {
                    return Ok(identity);
                }
            }
        }
    }

    let identity = generate_postgres_bootstrap_identity();
    let serialized = serde_json::to_string_pretty(&identity).map_err(|e| e.to_string())?;
    fs::write(&path, serialized).map_err(|e| e.to_string())?;
    Ok(identity)
}

fn save_postgres_bootstrap_identity(
    app: &tauri::AppHandle,
    identity: &PostgresBootstrapIdentity,
) -> Result<(), String> {
    let serialized = serde_json::to_string_pretty(identity).map_err(|e| e.to_string())?;
    fs::write(postgres_bootstrap_identity_path(app)?, serialized).map_err(|e| e.to_string())
}

fn save_postgres_runtime_config(
    app: &tauri::AppHandle,
    config: &PostgresRuntimeConfig,
) -> Result<(), String> {
    let path = postgres_runtime_config_path(app)?;
    let serialized = serde_json::to_string_pretty(config).map_err(|e| e.to_string())?;
    fs::write(&path, serialized).map_err(|e| e.to_string())
}

fn load_postgres_runtime_config(app: &tauri::AppHandle) -> Result<PostgresRuntimeConfig, String> {
    let identity = load_or_create_postgres_bootstrap_identity(app)?;
    let fallback = postgres_runtime_config_from_identity(&identity);
    let path = postgres_runtime_config_path(app)?;
    if path.exists() {
        if let Ok(text) = fs::read_to_string(&path) {
            if let Ok(mut config) = serde_json::from_str::<PostgresRuntimeConfig>(&text) {
                if !config.host.trim().is_empty() && !config.database.trim().is_empty() {
                    config.network_mode = normalize_postgres_network_mode(&config.network_mode);
                    return Ok(config);
                }
            }
        }
    }
    save_postgres_runtime_config(app, &fallback)?;
    Ok(fallback)
}

async fn can_reach_postgres(host: &str, port: u16, timeout: Duration) -> bool {
    matches!(
        tokio::time::timeout(timeout, tokio::net::TcpStream::connect((host, port))).await,
        Ok(Ok(_))
    )
}

fn bundled_postgres_psql_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    Ok(PathBuf::from(
        bundled_postgres::resolve_paths(app)?.psql_binary,
    ))
}

fn normalize_postgres_network_mode(mode: &str) -> String {
    match mode.trim().to_lowercase().as_str() {
        "device" | "local" => "device".to_string(),
        "network" | "lan" => "network".to_string(),
        "internet" => "internet".to_string(),
        _ => "device".to_string(),
    }
}

fn sql_escape_literal(value: &str) -> String {
    value.replace('\'', "''")
}

fn sql_escape_identifier(value: &str) -> String {
    value.replace('"', "\"\"")
}

fn is_valid_postgres_superuser_name(value: &str) -> bool {
    !value.trim().is_empty()
        && value.chars().enumerate().all(|(index, ch)| {
            if index == 0 {
                ch == '_' || ch.is_ascii_alphabetic()
            } else {
                ch == '_' || ch.is_ascii_alphanumeric()
            }
        })
}

fn write_postgres_managed_config(
    app: &tauri::AppHandle,
    mode: &str,
    identity: &PostgresBootstrapIdentity,
    local_ip: Option<&str>,
) -> Result<(), String> {
    let paths = bundled_postgres::resolve_paths(app)?;
    bundled_postgres::write_managed_config(&paths, mode, &identity.superuser_name, "", local_ip)
        .map(|_| ())
}

async fn ensure_postgres_experiment_text_array_column(
    client: &tokio_postgres::Client,
    table_name: &str,
    column_name: &str,
    legacy_single_value_column_name: &str,
) -> Result<(), String> {
    let column_metadata = client
        .query_opt(
            "
            SELECT data_type, udt_name
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = $1
              AND column_name = $2
            ",
            &[&table_name, &column_name],
        )
        .await
        .map_err(|e| format!("Could not inspect PostgreSQL experiment schema column {table_name}.{column_name}: {e}"))?;

    let has_text_array_type = column_metadata.as_ref().is_some_and(|row| {
        let data_type: String = row.get(0);
        let udt_name: String = row.get(1);
        data_type == "ARRAY" && udt_name == "_text"
    });

    let escaped_table_name = format!("\"{}\"", sql_escape_identifier(table_name));
    let escaped_column_name = format!("\"{}\"", sql_escape_identifier(column_name));
    let escaped_legacy_column_name = format!(
        "\"{}\"",
        sql_escape_identifier(legacy_single_value_column_name)
    );

    if !has_text_array_type {
        if column_metadata.is_some() {
            client
                .batch_execute(
                    format!("ALTER TABLE {escaped_table_name} DROP COLUMN {escaped_column_name};").as_str(),
                )
                .await
                .map_err(|e| {
                    format!(
                        "Could not reset PostgreSQL experiment schema column {table_name}.{column_name}: {e}"
                    )
                })?;
        }

        client
            .batch_execute(
                format!(
                    "
                    ALTER TABLE {escaped_table_name} ADD COLUMN {escaped_column_name} TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];
                    UPDATE {escaped_table_name}
                    SET {escaped_column_name} = CASE
                        WHEN {escaped_legacy_column_name} IS NOT NULL AND TRIM({escaped_legacy_column_name}) <> '' THEN ARRAY[{escaped_legacy_column_name}]
                        ELSE ARRAY[]::TEXT[]
                    END;
                    "
                )
                .as_str(),
            )
            .await
            .map_err(|e| {
                format!(
                    "Could not recreate PostgreSQL experiment schema column {table_name}.{column_name}: {e}"
                )
            })?;
        return Ok(());
    }

    client
        .batch_execute(
            format!(
                "
                UPDATE {escaped_table_name}
                SET {escaped_column_name} = COALESCE({escaped_column_name}, ARRAY[]::TEXT[]);
                UPDATE {escaped_table_name}
                SET {escaped_column_name} = ARRAY[{escaped_legacy_column_name}]
                WHERE cardinality({escaped_column_name}) = 0
                  AND {escaped_legacy_column_name} IS NOT NULL
                  AND TRIM({escaped_legacy_column_name}) <> '';
                "
            )
            .as_str(),
        )
        .await
        .map_err(|e| {
            format!("Could not normalize PostgreSQL experiment schema column {table_name}.{column_name}: {e}")
        })?;

    Ok(())
}

fn run_psql_command_with_binary(
    psql_path: &Path,
    host: &str,
    port: u16,
    user: &str,
    password: &str,
    database: &str,
    sql: &str,
) -> Result<String, String> {
    let output = Command::new(psql_path)
        .env("PGPASSWORD", password)
        .args([
            "-v",
            "ON_ERROR_STOP=1",
            "-h",
            host,
            "-p",
            &port.to_string(),
            "-U",
            user,
            "-d",
            database,
            "-tAc",
            sql,
        ])
        .output()
        .map_err(|e| format!("Failed to run psql at {}: {e}", psql_path.display()))?;

    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
    } else {
        Err(String::from_utf8_lossy(&output.stderr).trim().to_string())
    }
}

fn postgres_login_failure_is_runtime_unavailable(message: &str) -> bool {
    let lower = message.to_lowercase();
    if lower.contains("password authentication failed")
        || lower.contains("authentication failed")
        || lower.contains("role \"")
    {
        return false;
    }
    lower.contains("could not connect")
        || lower.contains("connection refused")
        || lower.contains("server closed the connection")
        || lower.contains("database system is starting up")
        || lower.contains("no pg_hba.conf entry")
        || lower.contains("timeout")
}

async fn connect_postgres_runtime(
    app: &tauri::AppHandle,
) -> Result<(CachedPostgresClient, PostgresConnectionLease), String> {
    let mut config = load_postgres_runtime_config(app)?;
    let auth_state = app.state::<PostgresExperimentAuthState>();
    let Some(session) = get_postgres_runtime_auth_session(&auth_state) else {
        return Err(
            "Sign in to PostgreSQL before opening the KanQual control database.".to_string(),
        );
    };
    config.user = session.postgres_username;
    config.password = session.postgres_password;
    match connect_postgres_database_with_config(app, &config).await {
        Ok(connection) => Ok(connection),
        Err(primary_error) => {
            let normalized_mode = normalize_postgres_network_mode(&config.network_mode);
            let host = config.host.trim().to_lowercase();
            if normalized_mode == "device"
                || host == POSTGRES_DEFAULT_HOST
                || host == "localhost"
                || host == "::1"
            {
                return Err(primary_error);
            }

            let mut fallback = config.clone();
            fallback.network_mode = "device".to_string();
            fallback.host = POSTGRES_DEFAULT_HOST.to_string();
            fallback.updated_at_ms = current_time_ms();
            match connect_postgres_database_with_config(app, &fallback).await {
                Ok(connection) => {
                    let _ = save_postgres_runtime_config(app, &fallback);
                    Ok(connection)
                }
                Err(fallback_error) => Err(format!(
                    "{primary_error} Device-mode fallback also failed: {fallback_error}"
                )),
            }
        }
    }
}

async fn connect_postgres_database(
    app: &tauri::AppHandle,
    database: &str,
) -> Result<(CachedPostgresClient, PostgresConnectionLease), String> {
    let mut config = load_postgres_runtime_config(app)?;
    config.database = database.to_string();
    let auth_state = app.state::<PostgresExperimentAuthState>();
    let Some(session) = get_postgres_runtime_auth_session(&auth_state) else {
        return Err("Sign in to PostgreSQL before opening a project database.".to_string());
    };
    config.user = session.postgres_username;
    config.password = session.postgres_password;
    connect_postgres_database_with_config(app, &config).await
}

