fn normalize_postgres_experiment_theme_state(
    theme_state: PostgresExperimentThemeState,
) -> PostgresExperimentThemeState {
    let mut presets = theme_state
        .presets
        .into_iter()
        .filter_map(|preset| {
            let id = preset.id.trim().to_string();
            if id.is_empty() {
                return None;
            }
            Some(PostgresExperimentThemePreset {
                id,
                name: preset.name.trim().to_string(),
                base: normalize_postgres_experiment_theme(&preset.base),
                colors: preset
                    .colors
                    .into_iter()
                    .filter_map(|(key, value)| {
                        let trimmed_key = key.trim().to_string();
                        let trimmed_value = value.trim().to_string();
                        if trimmed_key.is_empty() || trimmed_value.is_empty() {
                            None
                        } else {
                            Some((trimmed_key, trimmed_value))
                        }
                    })
                    .collect(),
                border_radius: clamp_postgres_experiment_i32(preset.border_radius, 0, 20),
                border_width: clamp_postgres_experiment_i32(preset.border_width, 1, 4),
                canvas_grid_enabled: preset.canvas_grid_enabled,
                canvas_grid_density: clamp_postgres_experiment_i32(
                    preset.canvas_grid_density,
                    8,
                    48,
                ),
            })
        })
        .take(100)
        .collect::<Vec<_>>();

    let active_preset_id = theme_state
        .active_preset_id
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty() && presets.iter().any(|preset| preset.id == *value));

    PostgresExperimentThemeState {
        light_overrides: theme_state
            .light_overrides
            .into_iter()
            .filter_map(|(key, value)| {
                let trimmed_key = key.trim().to_string();
                let trimmed_value = value.trim().to_string();
                if trimmed_key.is_empty() || trimmed_value.is_empty() {
                    None
                } else {
                    Some((trimmed_key, trimmed_value))
                }
            })
            .collect(),
        dark_overrides: theme_state
            .dark_overrides
            .into_iter()
            .filter_map(|(key, value)| {
                let trimmed_key = key.trim().to_string();
                let trimmed_value = value.trim().to_string();
                if trimmed_key.is_empty() || trimmed_value.is_empty() {
                    None
                } else {
                    Some((trimmed_key, trimmed_value))
                }
            })
            .collect(),
        border_radius: clamp_postgres_experiment_i32(theme_state.border_radius, 0, 20),
        border_width: clamp_postgres_experiment_i32(theme_state.border_width, 1, 4),
        canvas_grid_enabled: theme_state.canvas_grid_enabled,
        canvas_grid_density: clamp_postgres_experiment_i32(theme_state.canvas_grid_density, 8, 48),
        presets: std::mem::take(&mut presets),
        active_preset_id,
    }
}

fn normalize_postgres_experiment_getting_started_state(value: Value) -> Value {
    let mut state = default_postgres_experiment_getting_started_state();
    let Some(target) = state.as_object_mut() else {
        return default_postgres_experiment_getting_started_state();
    };
    if let Some(source) = value.as_object() {
        for key in [
            "dismissed",
            "completed",
            "step",
            "projectId",
            "userId",
            "sourceId",
            "codeId",
            "adminUserId",
            "currentActor",
            "temporaryUsername",
        ] {
            if let Some(next_value) = source.get(key) {
                target.insert(key.to_string(), next_value.clone());
            }
        }
    }
    for key in ["dismissed", "completed"] {
        let next = target.get(key).and_then(Value::as_bool).unwrap_or(false);
        target.insert(key.to_string(), Value::Bool(next));
    }
    for key in [
        "step",
        "projectId",
        "userId",
        "sourceId",
        "codeId",
        "adminUserId",
        "currentActor",
        "temporaryUsername",
    ] {
        let next = target
            .get(key)
            .and_then(Value::as_str)
            .unwrap_or_default()
            .trim()
            .to_string();
        target.insert(key.to_string(), Value::String(next));
    }
    state
}

