async fn load_postgres_experiment_project_record(
    app: &tauri::AppHandle,
    project_id: &str,
) -> Result<PostgresExperimentProject, String> {
    ensure_postgres_experiment_control_schema(app).await?;
    let (client, connection_task) = connect_postgres_runtime(app).await?;
    let row = client
        .query_opt(
            "
            SELECT id, database_name, storage_path, creation_source, active, disabled_at::text, created_at::text, updated_at::text, COALESCE(to_jsonb(projects)->>'created_by_username', '')
            FROM projects
            WHERE id = $1
            ",
            &[&project_id],
        )
        .await
        .map_err(|e| format!("Could not load PostgreSQL experiment project: {e}"))?;
    connection_task.abort();

    let Some(row) = row else {
        return Err("The PostgreSQL experiment project could not be found.".to_string());
    };

    let registry = PostgresExperimentProjectRegistryRecord {
        id: row.get(0),
        database_name: row.get(1),
        storage_path: row.get(2),
        creation_source: row.get(3),
        active: row.get(4),
        disabled_at: row.get(5),
        created_at: row.get(6),
        updated_at: row.get(7),
        created_by_username: row.get(8),
    };

    load_postgres_experiment_project_from_registry(app, registry).await
}

fn row_to_postgres_experiment_app_user_record(
    row: tokio_postgres::Row,
) -> PostgresExperimentAppUserRecord {
    PostgresExperimentAppUserRecord {
        user: PostgresExperimentAppUser {
            id: row.get(0),
            name: row.get(1),
            username: row.get(2),
            role: row.get(3),
            active: row.get(4),
            disabled_at: row.get(5),
            must_change_password: row.get(6),
            login_blocked_until_ms: None,
            login_permanently_blocked: false,
            login_failed_attempts_last_hour: 0,
            created_at: row.get(7),
            updated_at: row.get(8),
            last_login_at: row.get(9),
        },
    }
}

fn with_postgres_auth_block_state(
    app: &tauri::AppHandle,
    mut user: PostgresExperimentAppUser,
) -> PostgresExperimentAppUser {
    if let Some(entry) = active_postgres_auth_block_entry(app, &user.username) {
        user.login_blocked_until_ms = entry.blocked_until_ms;
        user.login_permanently_blocked = entry.permanently_blocked;
        user.login_failed_attempts_last_hour = entry.failed_attempts_ms.len();
    }
    user
}

