async fn load_postgres_experiment_app_user_last_login_map(
    app: &tauri::AppHandle,
    user_ids: &[String],
) -> Result<HashMap<String, Option<String>>, String> {
    let user_ids: Vec<String> = user_ids
        .iter()
        .map(|id| id.trim().to_string())
        .filter(|id| !id.is_empty())
        .collect();
    if user_ids.is_empty() {
        return Ok(HashMap::new());
    }

    let (client, connection_task) = connect_postgres_runtime(app).await?;
    let rows = client
        .query(
            "
            SELECT id, last_login_at::text
            FROM app_users
            WHERE id = ANY($1)
            ",
            &[&user_ids],
        )
        .await
        .map_err(|e| format!("Could not load PostgreSQL app user activity: {e}"))?;
    connection_task.abort();

    Ok(rows
        .into_iter()
        .map(|row| {
            (
                row.get::<usize, String>(0),
                row.get::<usize, Option<String>>(1),
            )
        })
        .collect())
}

async fn resolve_postgres_experiment_auth_session(
    app: &tauri::AppHandle,
    runtime_auth_state: Option<&tauri::State<'_, PostgresExperimentAuthState>>,
) -> Result<Option<PostgresExperimentAuthSession>, String> {
    let runtime_session =
        runtime_auth_state.and_then(|state| get_postgres_runtime_auth_session(state));
    if let Some(stored_session) = runtime_session {
        if stored_session.auth_kind == "postgres_admin" {
            let identity = load_or_create_postgres_bootstrap_identity(app)?;
            return Ok(Some(PostgresExperimentAuthSession {
                auth_kind: "postgres_admin".to_string(),
                user: build_postgres_experiment_local_admin_user(&identity),
                started_at_ms: stored_session.started_at_ms,
            }));
        }

        let Some(user_record) =
            load_postgres_experiment_app_user_by_id(app, &stored_session.user_id).await?
        else {
            if let Some(state) = runtime_auth_state {
                set_postgres_runtime_auth_session(state, None);
            }
            clear_postgres_connection_cache(app);
            return Ok(None);
        };
        if !user_record.user.active {
            append_postgres_experiment_auth_diagnostics_best_effort(
                app,
                "postgres.auth.session",
                "expired",
                "Stored PostgreSQL app user session was cleared because the user is disabled.",
                serde_json::json!({
                    "userId": user_record.user.id.clone(),
                    "username": user_record.user.username.clone(),
                }),
            );
            if let Some(state) = runtime_auth_state {
                set_postgres_runtime_auth_session(state, None);
            }
            clear_postgres_connection_cache(app);
            return Ok(None);
        }

        return Ok(Some(PostgresExperimentAuthSession {
            auth_kind: "app_user".to_string(),
            user: user_record.user,
            started_at_ms: stored_session.started_at_ms,
        }));
    }
    Ok(None)
}

async fn require_postgres_experiment_auth_session(
    app: &tauri::AppHandle,
    runtime_auth_state: Option<&tauri::State<'_, PostgresExperimentAuthState>>,
) -> Result<PostgresExperimentAuthSession, String> {
    ensure_postgres_experiment_auth_ready(app).await?;
    resolve_postgres_experiment_auth_session(app, runtime_auth_state)
        .await?
        .ok_or_else(|| "Sign in to the PostgreSQL experiment first.".to_string())
}

fn postgres_experiment_session_is_admin(session: &PostgresExperimentAuthSession) -> bool {
    session.auth_kind == "postgres_admin" || session.user.role == "administrator"
}

async fn postgres_experiment_project_membership_role(
    app: &tauri::AppHandle,
    project: &PostgresExperimentProject,
    session: &PostgresExperimentAuthSession,
) -> Result<Option<String>, String> {
    postgres_experiment_project_membership_role_for_database(
        app,
        &project.database_name,
        &session.user.id,
        &session.user.username,
    )
    .await
}

async fn postgres_experiment_project_membership_role_for_database(
    app: &tauri::AppHandle,
    database_name: &str,
    app_user_id: &str,
    _username: &str,
) -> Result<Option<String>, String> {
    let normalized_app_user_id = app_user_id.trim().to_string();
    if normalized_app_user_id.is_empty() {
        return Ok(None);
    }

    let (client, connection_task) = connect_postgres_database(app, database_name).await?;
    let result = client
        .query_opt(
            "
            SELECT role
            FROM project_users
            WHERE app_user_id = $1
            LIMIT 1
            ",
            &[&normalized_app_user_id],
        )
        .await
        .map(|row| row.map(|row| row.get(0)))
        .map_err(|e| format!("Could not inspect PostgreSQL experiment project membership: {e}"));
    connection_task.abort();
    result
}

async fn require_postgres_experiment_project_access(
    app: &tauri::AppHandle,
    runtime_auth_state: Option<&tauri::State<'_, PostgresExperimentAuthState>>,
    project: &PostgresExperimentProject,
) -> Result<PostgresExperimentAuthSession, String> {
    let session = require_postgres_experiment_auth_session(app, runtime_auth_state).await?;
    if postgres_experiment_session_is_admin(&session) {
        return Ok(session);
    }
    if !project.active {
        return Err("This PostgreSQL project is disabled.".to_string());
    }

    let membership_role =
        postgres_experiment_project_membership_role(app, project, &session).await?;
    if membership_role.is_some() {
        return Ok(session);
    }

    Err("You do not have access to this PostgreSQL project.".to_string())
}

async fn require_postgres_experiment_project_membership_management(
    app: &tauri::AppHandle,
    runtime_auth_state: Option<&tauri::State<'_, PostgresExperimentAuthState>>,
    project: &PostgresExperimentProject,
) -> Result<PostgresExperimentAuthSession, String> {
    let session =
        require_postgres_experiment_project_access(app, runtime_auth_state, project).await?;
    if postgres_experiment_session_is_admin(&session) {
        return Ok(session);
    }

    let membership_role =
        postgres_experiment_project_membership_role(app, project, &session).await?;
    if matches!(membership_role.as_deref(), Some("owner" | "admin")) {
        return Ok(session);
    }

    Err("Only project owners or administrators can change project membership.".to_string())
}

