fn postgres_experiment_access_mode_from_runtime_config(config: &PostgresRuntimeConfig) -> String {
    let host = config.host.trim().to_lowercase();
    if host.is_empty() || host == "localhost" || host == "127.0.0.1" || host == "::1" {
        "local".to_string()
    } else {
        "remote".to_string()
    }
}

