fn normalize_attribute_options(options: &[String]) -> Vec<String> {
    options
        .iter()
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
        .map(|value| value.to_string())
        .collect()
}

fn normalize_postgres_experiment_attribute_data_type(value: &str) -> Option<&'static str> {
    match value.trim().to_ascii_lowercase().as_str() {
        "text" => Some("text"),
        "number" => Some("number"),
        "datetime" => Some("datetime"),
        "categorical" => Some("categorical"),
        _ => None,
    }
}

fn normalize_postgres_experiment_timeline_role(value: Option<&str>) -> Result<String, String> {
    let Some(value) = value else {
        return Ok(String::new());
    };
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "" | "none" => Ok(String::new()),
        "start" | "timeline_start" => Ok("timeline_start".to_string()),
        "end" | "timeline_end" => Ok("timeline_end".to_string()),
        "label" | "content" | "timeline_label" | "timeline_content" => {
            Ok("timeline_label".to_string())
        }
        "item_type" | "type" | "timeline_item_type" => Ok("timeline_item_type".to_string()),
        "group" | "lane" | "timeline_group" | "timeline_lane" => Ok("timeline_group".to_string()),
        _ => Err("Choose a valid timeline attribute role.".to_string()),
    }
}

fn validate_postgres_experiment_timeline_attribute_role(
    timeline_role: &str,
    data_type: &str,
    options: &[String],
    owner_label: &str,
) -> Result<(), String> {
    match timeline_role {
        "" => Ok(()),
        "timeline_start" | "timeline_end" => {
            if data_type == "datetime" {
                Ok(())
            } else {
                Err(format!(
                    "{owner_label} timeline start and end attributes must use the datetime type."
                ))
            }
        }
        "timeline_label" | "timeline_group" => {
            if data_type == "text" || data_type == "categorical" {
                Ok(())
            } else {
                Err(format!(
                    "{owner_label} timeline label and group attributes must use text or categorical values."
                ))
            }
        }
        "timeline_item_type" => {
            if data_type != "categorical" {
                return Err(format!(
                    "{owner_label} timeline item type attributes must use categorical values."
                ));
            }
            let allowed = ["point", "box", "range", "background"];
            if options.is_empty()
                || options
                    .iter()
                    .all(|option| allowed.contains(&option.trim().to_ascii_lowercase().as_str()))
            {
                Ok(())
            } else {
                Err(format!(
                    "{owner_label} timeline item type options must be point, box, range, or background."
                ))
            }
        }
        _ => Err("Choose a valid timeline attribute role.".to_string()),
    }
}

fn canonicalize_categorical_suggestion(value: &str, options: &[String]) -> String {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return String::new();
    }
    if let Some(exact_match) = options.iter().find(|option| option == &trimmed) {
        return exact_match.clone();
    }
    let folded = trimmed.to_ascii_lowercase();
    options
        .iter()
        .find(|option| option.trim().to_ascii_lowercase() == folded)
        .cloned()
        .unwrap_or_default()
}

fn normalize_proper_noun_candidate(value: &str) -> Option<String> {
    let trimmed = value
        .trim()
        .trim_matches(|ch: char| matches!(ch, '"' | '\'' | '(' | ')' | '[' | ']'));
    if trimmed.len() < 2 || trimmed.len() > 80 {
        return None;
    }
    if !trimmed.chars().any(|ch| ch.is_alphabetic()) {
        return None;
    }
    let lower = trimmed.to_ascii_lowercase();
    let blocked = [
        "interviewer",
        "interviewee",
        "participant",
        "participants",
        "moderator",
        "facilitator",
        "speaker",
        "respondent",
        "question",
        "answer",
        "metadata",
        "unknown",
        "n/a",
    ];
    if blocked.contains(&lower.as_str()) {
        return None;
    }
    Some(trimmed.to_string())
}

fn extract_proper_noun_candidates_from_text(text: &str) -> Vec<String> {
    let mut candidates = Vec::new();
    let mut seen = HashSet::new();
    let mut current: Vec<String> = Vec::new();

    let flush_current =
        |current: &mut Vec<String>, candidates: &mut Vec<String>, seen: &mut HashSet<String>| {
            if current.is_empty() {
                return;
            }
            let candidate = current.join(" ");
            current.clear();
            let Some(normalized) = normalize_proper_noun_candidate(&candidate) else {
                return;
            };
            let token_count = normalized.split_whitespace().count();
            let is_acronym = normalized
                .chars()
                .filter(|ch| ch.is_alphabetic())
                .all(|ch| ch.is_uppercase());
            if token_count < 2 && !is_acronym {
                return;
            }
            if seen.insert(normalized.to_ascii_lowercase()) {
                candidates.push(normalized);
            }
        };

    for raw_token in text.split_whitespace() {
        let token = raw_token
            .trim_matches(|ch: char| {
                matches!(
                    ch,
                    '"' | '\''
                        | '('
                        | ')'
                        | '['
                        | ']'
                        | '{'
                        | '}'
                        | ','
                        | ';'
                        | ':'
                        | '.'
                        | '?'
                        | '!'
                )
            })
            .trim();
        if token.is_empty() {
            flush_current(&mut current, &mut candidates, &mut seen);
            continue;
        }

        let mut chars = token.chars();
        let first = chars.next().unwrap_or_default();
        let has_letter = token.chars().any(|ch| ch.is_alphabetic());
        let looks_proper = has_letter
            && (first.is_uppercase()
                || token
                    .chars()
                    .filter(|ch| ch.is_alphabetic())
                    .all(|ch| ch.is_uppercase()));
        if looks_proper {
            current.push(token.to_string());
        } else {
            flush_current(&mut current, &mut candidates, &mut seen);
        }
    }
    flush_current(&mut current, &mut candidates, &mut seen);
    candidates
}

fn looks_like_named_speaker_label(value: &str) -> bool {
    let Some(normalized) = normalize_proper_noun_candidate(value) else {
        return false;
    };
    if normalized
        .chars()
        .all(|ch| ch.is_uppercase() || !ch.is_alphabetic())
        && normalized.len() <= 4
    {
        return false;
    }
    if normalized.chars().all(|ch| ch.is_alphanumeric()) && normalized.len() <= 3 {
        return false;
    }
    true
}

fn is_interviewer_style_speaker_label(value: &str) -> bool {
    let normalized = value
        .trim()
        .trim_matches(|ch: char| matches!(ch, '"' | '\'' | '(' | ')' | '[' | ']'))
        .to_ascii_lowercase();
    matches!(
        normalized.as_str(),
        "interviewer" | "moderator" | "facilitator" | "host" | "researcher" | "q" | "q1"
    )
}

fn extract_leading_inline_speaker_label(text: &str) -> Option<(String, String)> {
    let trimmed = text.trim_start();
    let leading_ws_len = text.len().saturating_sub(trimmed.len());
    let leading_ws = &text[..leading_ws_len];
    if trimmed.is_empty() {
        return None;
    }

    if let Some(rest) = trimmed.strip_prefix('[') {
        let end = rest.find(']')?;
        let candidate = rest[..end].trim();
        let after = rest[end + 1..].trim_start();
        if candidate.len() < 1 || candidate.len() > 40 {
            return None;
        }
        if !after.starts_with(':') && !after.starts_with('-') && !after.starts_with('—') {
            return None;
        }
        if !candidate.chars().any(|ch| ch.is_alphabetic()) {
            return None;
        }
        if !candidate
            .chars()
            .all(|ch| ch.is_alphanumeric() || matches!(ch, ' ' | '_' | '-' | '.'))
        {
            return None;
        }
        let after_delimiter = after[after.chars().next()?.len_utf8()..].trim_start();
        let cleaned = format!("{}{}", leading_ws, after_delimiter)
            .trim()
            .to_string();
        return Some((candidate.to_string(), cleaned));
    }

    let first_line_end = trimmed.find('\n').unwrap_or(trimmed.len());
    let first_line = &trimmed[..first_line_end];
    let delimiter = [":", " - ", " – ", " — "]
        .into_iter()
        .filter_map(|pattern| first_line.find(pattern).map(|index| (index, pattern)))
        .min_by_key(|(index, _)| *index)?;
    let delimiter_index = delimiter.0;
    let delimiter_text = delimiter.1;
    if delimiter_index == 0 || delimiter_index > 32 {
        return None;
    }
    let candidate = first_line[..delimiter_index].trim();
    if candidate.len() < 1 || candidate.len() > 32 {
        return None;
    }
    if !candidate.chars().any(|ch| ch.is_alphabetic()) {
        return None;
    }
    if !candidate
        .chars()
        .all(|ch| ch.is_alphanumeric() || matches!(ch, ' ' | '_' | '-' | '.'))
    {
        return None;
    }
    let after_delimiter = trimmed[delimiter_index + delimiter_text.len()..].trim_start();
    let cleaned = format!("{}{}", leading_ws, after_delimiter)
        .trim()
        .to_string();
    Some((candidate.to_string(), cleaned))
}

fn extract_transcript_leading_metadata(text: &str) -> (String, Option<String>, String) {
    let mut remaining = text.to_string();
    let mut speaker_id: Option<String> = None;
    let mut timestamps: Vec<String> = Vec::new();

    loop {
        let mut changed = false;

        let (without_timestamps, timestamp_text) = extract_leading_timestamp_metadata(&remaining);
        if !timestamp_text.is_empty() {
            timestamps.push(timestamp_text);
            remaining = without_timestamps;
            changed = true;
        }

        if speaker_id.is_none() {
            if let Some((detected_speaker_id, without_speaker_label)) =
                extract_leading_inline_speaker_label(&remaining)
            {
                speaker_id = Some(detected_speaker_id);
                remaining = without_speaker_label;
                changed = true;
            }
        }

        if !changed {
            break;
        }
    }

    (
        remaining.trim().to_string(),
        speaker_id,
        timestamps.join(" "),
    )
}

fn infer_inline_speaker_label(text: &str) -> Option<String> {
    let (_, speaker_id, _) = extract_transcript_leading_metadata(text);
    speaker_id
}

fn split_text_on_inline_speaker_labels(text: &str) -> Vec<String> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Vec::new();
    }

    let mut segments: Vec<String> = Vec::new();
    let mut current = String::new();

    for line in trimmed.split_inclusive('\n') {
        let has_inline_label = infer_inline_speaker_label(line.trim_start()).is_some();
        if has_inline_label && !current.trim().is_empty() {
            segments.push(current.trim().to_string());
            current.clear();
        }
        current.push_str(line);
    }

    if !current.trim().is_empty() {
        segments.push(current.trim().to_string());
    }

    if segments.is_empty() {
        vec![trimmed.to_string()]
    } else {
        segments
    }
}

fn is_supported_timestamp_body(body: &str) -> bool {
    let parts = body.split('-').map(str::trim).collect::<Vec<_>>();
    if parts.is_empty() || parts.len() > 2 {
        return false;
    }
    parts.iter().all(|part| {
        let fields = part.split(':').collect::<Vec<_>>();
        (fields.len() == 2 || fields.len() == 3)
            && fields
                .iter()
                .all(|field| !field.is_empty() && field.chars().all(|ch| ch.is_ascii_digit()))
    })
}

fn extract_leading_timestamp_metadata(text: &str) -> (String, String) {
    let trimmed = text.trim_start();
    let leading_ws_len = text.len().saturating_sub(trimmed.len());
    let leading_ws = &text[..leading_ws_len];
    let mut remaining = trimmed;
    let mut timestamps: Vec<String> = Vec::new();

    loop {
        let Some(rest) = remaining.strip_prefix('[') else {
            break;
        };
        let Some(end) = rest.find(']') else {
            break;
        };
        let candidate = rest[..end].trim();
        if !is_supported_timestamp_body(candidate) {
            break;
        }
        timestamps.push(format!("[{}]", candidate));
        remaining = rest[end + 1..].trim_start();
    }

    let cleaned = if timestamps.is_empty() {
        text.trim().to_string()
    } else {
        format!("{}{}", leading_ws, remaining).trim().to_string()
    };

    (cleaned, timestamps.join(" "))
}

