async fn load_postgres_experiment_source_type_settings_for_client(
    client: &tokio_postgres::Client,
    project_id: &str,
) -> Result<Vec<PostgresExperimentSourceTypeSetting>, String> {
    let rows = client
        .query(
            "
            SELECT source_kind, name, description, shape, color, outline_color, fill, fill_transparency, outline_width, image_storage_path, created_at::text, updated_at::text
            FROM source_type_settings
            ORDER BY CASE source_kind
                WHEN 'Text' THEN 1
                WHEN 'Transcript' THEN 2
                WHEN 'PDF' THEN 3
                WHEN 'Image' THEN 4
                WHEN 'Audio' THEN 5
                WHEN 'Video' THEN 6
                ELSE 7
            END, lower(name) ASC
            ",
            &[],
        )
        .await
        .map_err(|e| format!("Could not load PostgreSQL experiment source type settings: {e}"))?;
    let mut by_kind: HashMap<String, PostgresExperimentSourceTypeSetting> = rows
        .into_iter()
        .map(|row| {
            let setting = map_postgres_experiment_source_type_setting_row(project_id, row);
            (setting.source_kind.clone(), setting)
        })
        .collect();
    let source_kinds = ["Text", "Transcript", "PDF", "Image", "Audio", "Video"];
    Ok(source_kinds
        .iter()
        .map(|source_kind| {
            by_kind.remove(*source_kind).unwrap_or_else(|| {
                default_postgres_experiment_source_type_setting(project_id, source_kind)
            })
        })
        .collect())
}

async fn delete_expired_postgres_experiment_source_locks_for_client(
    client: &impl GenericClient,
    now_ms: i64,
) -> Result<(), String> {
    client
        .execute(
            "
            DELETE FROM source_lock_kicks
            WHERE expires_at_ms <= $1
            ",
            &[&now_ms],
        )
        .await
        .map_err(|e| {
            format!("Could not clear expired PostgreSQL experiment source lock kicks: {e}")
        })?;
    client
        .execute(
            "
            DELETE FROM source_locks
            WHERE expires_at_ms <= $1
            ",
            &[&now_ms],
        )
        .await
        .map_err(|e| format!("Could not clear expired PostgreSQL experiment source locks: {e}"))?;
    Ok(())
}

