fn normalize_postgres_experiment_object_type_id_list(values: Vec<String>) -> Vec<String> {
    normalize_postgres_experiment_string_id_list(values)
}

fn normalize_postgres_experiment_string_id_list(values: Vec<String>) -> Vec<String> {
    let mut seen = HashSet::new();
    values
        .into_iter()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .filter(|value| seen.insert(value.clone()))
        .collect()
}

fn normalize_postgres_experiment_source_kind_list(values: Vec<String>) -> Vec<String> {
    let mut seen = HashSet::new();
    values
        .into_iter()
        .filter_map(|value| normalize_postgres_experiment_source_kind(&value).map(str::to_string))
        .filter(|value| seen.insert(value.clone()))
        .collect()
}

async fn load_postgres_experiment_relationship_type_for_client(
    client: &tokio_postgres::Client,
    relationship_type_id: &str,
) -> Result<
    (
        String,
        String,
        Vec<String>,
        Vec<String>,
        Vec<String>,
        Vec<String>,
    ),
    String,
> {
    let normalized_id = relationship_type_id.trim().to_string();
    if normalized_id.is_empty() {
        return Err("Choose a relationship type.".to_string());
    }
    let row = client
        .query_opt(
            "
            SELECT
                id,
                name,
                CASE
                    WHEN array_length(from_object_type_ids, 1) IS NOT NULL THEN from_object_type_ids
                    WHEN from_object_type_id IS NOT NULL THEN ARRAY[from_object_type_id]
                    ELSE ARRAY[]::TEXT[]
                END,
                CASE
                    WHEN array_length(to_object_type_ids, 1) IS NOT NULL THEN to_object_type_ids
                    WHEN to_object_type_id IS NOT NULL THEN ARRAY[to_object_type_id]
                    ELSE ARRAY[]::TEXT[]
                END,
                from_source_kinds,
                to_source_kinds
            FROM relationship_types
            WHERE id = $1
            ",
            &[&normalized_id],
        )
        .await
        .map_err(|e| format!("Could not load PostgreSQL experiment relationship type: {e}"))?;
    row.map(|row| {
        (
            row.get(0),
            row.get(1),
            row.get(2),
            row.get(3),
            row.get(4),
            row.get(5),
        )
    })
    .ok_or_else(|| "The selected relationship type could not be found.".to_string())
}

fn normalize_postgres_experiment_relationship_endpoint_type(value: &str) -> Option<&'static str> {
    match value.trim().to_ascii_lowercase().as_str() {
        "" | "object" => Some("object"),
        "source" => Some("source"),
        _ => None,
    }
}

fn resolve_postgres_experiment_relationship_endpoint(
    entity_type: Option<String>,
    entity_id: Option<String>,
    legacy_object_id: Option<String>,
) -> Result<(String, String, Option<String>), String> {
    let resolved_entity_type = normalize_postgres_experiment_relationship_endpoint_type(
        entity_type.as_deref().unwrap_or("object"),
    )
    .ok_or_else(|| "Relationship endpoints must be objects or sources.".to_string())?
    .to_string();
    let resolved_entity_id = entity_id
        .as_deref()
        .or(legacy_object_id.as_deref())
        .unwrap_or("")
        .trim()
        .to_string();
    if resolved_entity_id.is_empty() {
        return Err("Choose both endpoints for the relationship.".to_string());
    }
    let object_id = if resolved_entity_type == "object" {
        Some(resolved_entity_id.clone())
    } else {
        None
    };
    Ok((resolved_entity_type, resolved_entity_id, object_id))
}

async fn validate_postgres_experiment_relationship_type_constraints_for_client(
    client: &tokio_postgres::Client,
    from_entity_type: &str,
    from_entity_id: &str,
    to_entity_type: &str,
    to_entity_id: &str,
    relationship_type_name: &str,
    allowed_from_object_type_ids: &[String],
    allowed_to_object_type_ids: &[String],
    allowed_from_source_kinds: &[String],
    allowed_to_source_kinds: &[String],
) -> Result<(), String> {
    let mut object_type_by_object_id: HashMap<String, Option<String>> = HashMap::new();
    let object_ids = [from_entity_type, to_entity_type]
        .into_iter()
        .zip([from_entity_id, to_entity_id])
        .filter_map(|(entity_type, entity_id)| {
            if entity_type == "object" {
                Some(entity_id.to_string())
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    if !object_ids.is_empty() {
        let rows = client
            .query(
                "
                SELECT id, object_type_id
                FROM research_objects
                WHERE id = ANY($1)
                ",
                &[&object_ids],
            )
            .await
            .map_err(|e| {
                format!("Could not validate PostgreSQL experiment relationship object types: {e}")
            })?;
        for row in rows {
            object_type_by_object_id.insert(row.get(0), row.get(1));
        }
        for object_id in &object_ids {
            if !object_type_by_object_id.contains_key(object_id) {
                return Err(
                    "One of the selected relationship objects could not be found.".to_string(),
                );
            }
        }
    }

    let mut source_kind_by_source_id: HashMap<String, String> = HashMap::new();
    let source_ids = [from_entity_type, to_entity_type]
        .into_iter()
        .zip([from_entity_id, to_entity_id])
        .filter_map(|(entity_type, entity_id)| {
            if entity_type == "source" {
                Some(entity_id.to_string())
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    if !source_ids.is_empty() {
        let rows = client
            .query(
                "
                SELECT id, source_kind
                FROM sources
                WHERE id = ANY($1)
                ",
                &[&source_ids],
            )
            .await
            .map_err(|e| {
                format!("Could not validate PostgreSQL experiment relationship source kinds: {e}")
            })?;
        for row in rows {
            source_kind_by_source_id.insert(row.get(0), row.get(1));
        }
        for source_id in &source_ids {
            if !source_kind_by_source_id.contains_key(source_id) {
                return Err(
                    "One of the selected relationship sources could not be found.".to_string(),
                );
            }
        }
    }

    if from_entity_type == "object" && !allowed_from_object_type_ids.is_empty() {
        let actual_from_object_type_id = object_type_by_object_id
            .get(from_entity_id)
            .and_then(|value| value.clone());
        if !actual_from_object_type_id
            .as_deref()
            .map(|value| {
                allowed_from_object_type_ids
                    .iter()
                    .any(|allowed_id| allowed_id == value)
            })
            .unwrap_or(false)
        {
            return Err(format!(
                "Relationships of type \"{relationship_type_name}\" require the source object to match its configured object type restriction."
            ));
        }
    }

    if to_entity_type == "object" && !allowed_to_object_type_ids.is_empty() {
        let actual_to_object_type_id = object_type_by_object_id
            .get(to_entity_id)
            .and_then(|value| value.clone());
        if !actual_to_object_type_id
            .as_deref()
            .map(|value| {
                allowed_to_object_type_ids
                    .iter()
                    .any(|allowed_id| allowed_id == value)
            })
            .unwrap_or(false)
        {
            return Err(format!(
                "Relationships of type \"{relationship_type_name}\" require the target object to match its configured object type restriction."
            ));
        }
    }

    if from_entity_type == "source" && !allowed_from_source_kinds.is_empty() {
        let actual_from_source_kind = source_kind_by_source_id.get(from_entity_id);
        if !actual_from_source_kind
            .map(|value| {
                allowed_from_source_kinds
                    .iter()
                    .any(|allowed| allowed == value)
            })
            .unwrap_or(false)
        {
            return Err(format!(
                "Relationships of type \"{relationship_type_name}\" require the source endpoint to match its configured source kind restriction."
            ));
        }
    }

    if to_entity_type == "source" && !allowed_to_source_kinds.is_empty() {
        let actual_to_source_kind = source_kind_by_source_id.get(to_entity_id);
        if !actual_to_source_kind
            .map(|value| {
                allowed_to_source_kinds
                    .iter()
                    .any(|allowed| allowed == value)
            })
            .unwrap_or(false)
        {
            return Err(format!(
                "Relationships of type \"{relationship_type_name}\" require the target endpoint to match its configured source kind restriction."
            ));
        }
    }

    Ok(())
}

async fn load_postgres_experiment_object_attribute_values_for_client(
    client: &tokio_postgres::Client,
) -> Result<HashMap<String, Vec<PostgresExperimentObjectAttributeValue>>, String> {
    let rows = client
        .query(
            "
            SELECT
                v.id,
                v.object_id,
                v.attribute_definition_id,
                d.name,
                d.data_type,
                v.value,
                d.sort_order
            FROM object_attribute_values v
            INNER JOIN object_attribute_definitions d ON d.id = v.attribute_definition_id
            ORDER BY d.sort_order ASC, d.created_at ASC, d.id ASC, v.created_at ASC, v.id ASC
            ",
            &[],
        )
        .await
        .map_err(|e| {
            format!("Could not load PostgreSQL experiment object attribute values: {e}")
        })?;
    let mut values_by_object_id: HashMap<String, Vec<PostgresExperimentObjectAttributeValue>> =
        HashMap::new();
    for row in rows {
        let object_id: String = row.get(1);
        values_by_object_id
            .entry(object_id.clone())
            .or_default()
            .push(PostgresExperimentObjectAttributeValue {
                id: row.get(0),
                object_id,
                attribute_definition_id: row.get(2),
                attribute_name: row.get(3),
                data_type: row.get(4),
                value: row.get(5),
                sort_order: row.get(6),
            });
    }
    Ok(values_by_object_id)
}

async fn save_postgres_experiment_object_attribute_values_for_client(
    client: &(impl GenericClient + Sync),
    object_id: &str,
    object_type_id: &str,
    attribute_values: &[PostgresExperimentObjectAttributeValueInput],
    change_context: &PostgresExperimentAttributeValueChangeContext,
) -> Result<(), String> {
    let normalized_object_type_id = object_type_id.trim().to_string();
    if normalized_object_type_id.is_empty() {
        return Err("Object type is required for object attributes.".to_string());
    }

    let definition_rows = client
        .query(
            "
            SELECT id, data_type, options_json
            FROM object_attribute_definitions
            WHERE object_type_id = $1
            ",
            &[&normalized_object_type_id],
        )
        .await
        .map_err(|e| format!("Could not validate PostgreSQL experiment object attributes: {e}"))?;

    let mut definitions_by_id: HashMap<String, (String, Vec<String>)> = HashMap::new();
    for row in definition_rows {
        let options_json: String = row.get(2);
        definitions_by_id.insert(
            row.get(0),
            (
                row.get(1),
                parse_postgres_experiment_attribute_options_json(&options_json),
            ),
        );
    }

    let existing_rows = client
        .query(
            "
            SELECT id, attribute_definition_id, value
            FROM object_attribute_values
            WHERE object_id = $1
            ",
            &[&object_id],
        )
        .await
        .map_err(|e| {
            format!("Could not load existing PostgreSQL experiment object attributes: {e}")
        })?;

    let mut existing_values_by_definition_id: HashMap<String, (String, String)> = HashMap::new();
    for row in existing_rows {
        existing_values_by_definition_id.insert(row.get(1), (row.get(0), row.get(2)));
    }

    let allowed_definition_ids: HashSet<String> = definitions_by_id.keys().cloned().collect();
    for (definition_id, (existing_value_id, existing_value)) in &existing_values_by_definition_id {
        if !allowed_definition_ids.contains(definition_id) {
            append_postgres_experiment_attribute_value_history_for_client(
                client,
                "object",
                object_id,
                definition_id,
                Some(existing_value_id),
                existing_value,
                "",
                "definition_removed",
                change_context,
            )
            .await?;
            client
                .execute(
                    "DELETE FROM object_attribute_values WHERE id = $1",
                    &[existing_value_id],
                )
                .await
                .map_err(|e| {
                    format!("Could not remove PostgreSQL experiment object attribute value: {e}")
                })?;
        }
    }

    let mut seen_definition_ids = HashSet::new();
    for input in attribute_values {
        let attribute_definition_id = input.attribute_definition_id.trim().to_string();
        if attribute_definition_id.is_empty() {
            return Err("Object attribute definition id is required.".to_string());
        }
        if !seen_definition_ids.insert(attribute_definition_id.clone()) {
            return Err("Each object attribute can only be supplied once per request.".to_string());
        }

        let trimmed_value = input.value.trim().to_string();
        let (data_type, options) = definitions_by_id
            .get(&attribute_definition_id)
            .cloned()
            .ok_or_else(|| {
                "One or more object attributes no longer exist in this project.".to_string()
            })?;

        if data_type == "categorical"
            && !trimmed_value.is_empty()
            && !options.iter().any(|option| option == &trimmed_value)
        {
            return Err(format!(
                "Choose one of the allowed values for object attribute \"{}\".",
                attribute_definition_id
            ));
        }

        if let Some((existing_value_id, existing_value)) =
            existing_values_by_definition_id.get(&attribute_definition_id)
        {
            if trimmed_value.is_empty() {
                append_postgres_experiment_attribute_value_history_for_client(
                    client,
                    "object",
                    object_id,
                    &attribute_definition_id,
                    Some(existing_value_id),
                    existing_value,
                    "",
                    "clear",
                    change_context,
                )
                .await?;
                client
                    .execute(
                        "DELETE FROM object_attribute_values WHERE id = $1",
                        &[existing_value_id],
                    )
                    .await
                    .map_err(|e| {
                        format!("Could not clear PostgreSQL experiment object attribute value: {e}")
                    })?;
            } else {
                append_postgres_experiment_attribute_value_history_for_client(
                    client,
                    "object",
                    object_id,
                    &attribute_definition_id,
                    Some(existing_value_id),
                    existing_value,
                    &trimmed_value,
                    "set",
                    change_context,
                )
                .await?;
                client
                    .execute(
                        "
                        UPDATE object_attribute_values
                        SET value = $2,
                            updated_at = NOW()
                        WHERE id = $1
                        ",
                        &[existing_value_id, &trimmed_value],
                    )
                    .await
                    .map_err(|e| {
                        format!(
                            "Could not update PostgreSQL experiment object attribute value: {e}"
                        )
                    })?;
            }
        } else if !trimmed_value.is_empty() {
            let value_id = generate_identifier();
            append_postgres_experiment_attribute_value_history_for_client(
                client,
                "object",
                object_id,
                &attribute_definition_id,
                Some(&value_id),
                "",
                &trimmed_value,
                "set",
                change_context,
            )
            .await?;
            client
                .execute(
                    "
                    INSERT INTO object_attribute_values (id, object_id, attribute_definition_id, value)
                    VALUES ($1, $2, $3, $4)
                    ",
                    &[&value_id, &object_id, &attribute_definition_id, &trimmed_value],
                )
                .await
                .map_err(|e| format!("Could not create PostgreSQL experiment object attribute value: {e}"))?;
        }
    }

    Ok(())
}

fn normalize_optional_postgres_experiment_text(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn normalize_postgres_experiment_event_time_precision(
    value: Option<&str>,
) -> Result<String, String> {
    let normalized = value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("exact")
        .to_ascii_lowercase();
    match normalized.as_str() {
        "exact" | "date" | "month" | "year" => Ok(normalized),
        _ => Err("Choose a valid event time precision.".to_string()),
    }
}

async fn save_postgres_experiment_event_fields_for_client(
    client: &(impl GenericClient + Sync),
    object_id: &str,
    object_type_system_key: Option<&str>,
    event_start_at: Option<&str>,
    event_end_at: Option<&str>,
    event_time_precision: Option<&str>,
    event_timezone: Option<&str>,
    event_is_instant: Option<bool>,
) -> Result<(), String> {
    if object_type_system_key == Some("event") {
        let start_at = normalize_optional_postgres_experiment_text(event_start_at)
            .ok_or_else(|| "Events require a start date/time.".to_string())?;
        let end_at = normalize_optional_postgres_experiment_text(event_end_at);
        let time_precision =
            normalize_postgres_experiment_event_time_precision(event_time_precision)?;
        let timezone = event_timezone.unwrap_or("").trim().to_string();
        let is_instant = event_is_instant.unwrap_or(false);
        client
            .execute(
                "
                INSERT INTO event_objects (object_id, start_at, end_at, time_precision, timezone, is_instant)
                VALUES ($1, $2::timestamptz, $3::timestamptz, $4, $5, $6)
                ON CONFLICT (object_id) DO UPDATE
                SET start_at = EXCLUDED.start_at,
                    end_at = EXCLUDED.end_at,
                    time_precision = EXCLUDED.time_precision,
                    timezone = EXCLUDED.timezone,
                    is_instant = EXCLUDED.is_instant,
                    updated_at = NOW()
                ",
                &[&object_id, &start_at, &end_at, &time_precision, &timezone, &is_instant],
            )
            .await
            .map_err(|e| format!("Could not save PostgreSQL experiment event fields: {e}"))?;
    } else {
        client
            .execute(
                "DELETE FROM event_objects WHERE object_id = $1",
                &[&object_id],
            )
            .await
            .map_err(|e| format!("Could not clear PostgreSQL experiment event fields: {e}"))?;
    }

    Ok(())
}

async fn load_postgres_experiment_object_for_client(
    client: &tokio_postgres::Client,
    project_id: &str,
    object_id: &str,
    attribute_values_by_object_id: &HashMap<String, Vec<PostgresExperimentObjectAttributeValue>>,
) -> Result<PostgresExperimentObject, String> {
    let row = client
        .query_one(
            "
            SELECT
                o.id,
                o.object_type_id,
                t.name,
                t.system_key,
                o.title,
                o.description,
                o.shape_override,
                o.color_override,
                o.outline_color_override,
                o.fill_override,
                o.fill_transparency_override,
                o.outline_width_override,
                o.image_storage_path,
                e.start_at::text,
                e.end_at::text,
                e.time_precision,
                NULLIF(e.timezone, ''),
                e.is_instant,
                o.created_at::text,
                o.updated_at::text
            FROM research_objects o
            LEFT JOIN object_types t ON t.id = o.object_type_id
            LEFT JOIN event_objects e ON e.object_id = o.id
            WHERE o.id = $1
            ",
            &[&object_id],
        )
        .await
        .map_err(|e| format!("Could not load PostgreSQL experiment object: {e}"))?;
    Ok(map_postgres_experiment_object_row(
        project_id,
        row,
        attribute_values_by_object_id,
    ))
}

async fn load_postgres_experiment_relationship_attribute_definitions_for_client(
    client: &tokio_postgres::Client,
    project_id: &str,
) -> Result<Vec<PostgresExperimentRelationshipAttributeDefinition>, String> {
    let rows = client
        .query(
            "
            SELECT d.id, d.relationship_type_id, t.name, d.name, d.data_type, d.description, d.options_json, d.timeline_role, d.sort_order, d.created_at::text, d.updated_at::text
            FROM relationship_attribute_definitions d
            LEFT JOIN relationship_types t ON t.id = d.relationship_type_id
            ORDER BY d.sort_order ASC, d.created_at ASC, d.id ASC
            ",
            &[],
        )
        .await
        .map_err(|e| format!("Could not load PostgreSQL experiment relationship attributes: {e}"))?;
    Ok(rows
        .into_iter()
        .map(|row| map_postgres_experiment_relationship_attribute_definition_row(project_id, row))
        .collect())
}

async fn load_postgres_experiment_relationship_attribute_values_for_client(
    client: &tokio_postgres::Client,
) -> Result<HashMap<String, Vec<PostgresExperimentRelationshipAttributeValue>>, String> {
    let rows = client
        .query(
            "
            SELECT
                v.id,
                v.relationship_id,
                v.attribute_definition_id,
                d.name,
                d.data_type,
                v.value,
                d.sort_order
            FROM relationship_attribute_values v
            INNER JOIN relationship_attribute_definitions d ON d.id = v.attribute_definition_id
            ORDER BY d.sort_order ASC, d.created_at ASC, d.id ASC, v.created_at ASC, v.id ASC
            ",
            &[],
        )
        .await
        .map_err(|e| {
            format!("Could not load PostgreSQL experiment relationship attribute values: {e}")
        })?;
    let mut values_by_relationship_id: HashMap<
        String,
        Vec<PostgresExperimentRelationshipAttributeValue>,
    > = HashMap::new();
    for row in rows {
        let relationship_id: String = row.get(1);
        values_by_relationship_id
            .entry(relationship_id.clone())
            .or_default()
            .push(PostgresExperimentRelationshipAttributeValue {
                id: row.get(0),
                relationship_id,
                attribute_definition_id: row.get(2),
                attribute_name: row.get(3),
                data_type: row.get(4),
                value: row.get(5),
                sort_order: row.get(6),
            });
    }
    Ok(values_by_relationship_id)
}

async fn save_postgres_experiment_relationship_attribute_values_for_client(
    client: &(impl GenericClient + Sync),
    relationship_id: &str,
    relationship_type_id: &str,
    attribute_values: &[PostgresExperimentRelationshipAttributeValueInput],
    change_context: &PostgresExperimentAttributeValueChangeContext,
) -> Result<(), String> {
    let normalized_relationship_type_id = relationship_type_id.trim().to_string();
    if normalized_relationship_type_id.is_empty() {
        return Err("Relationship type is required for relationship attributes.".to_string());
    }

    let definition_rows = client
        .query(
            "
            SELECT id, data_type, options_json
            FROM relationship_attribute_definitions
            WHERE relationship_type_id = $1
            ",
            &[&normalized_relationship_type_id],
        )
        .await
        .map_err(|e| {
            format!("Could not validate PostgreSQL experiment relationship attributes: {e}")
        })?;

    let mut definitions_by_id: HashMap<String, (String, Vec<String>)> = HashMap::new();
    for row in definition_rows {
        let options_json: String = row.get(2);
        definitions_by_id.insert(
            row.get(0),
            (
                row.get(1),
                parse_postgres_experiment_attribute_options_json(&options_json),
            ),
        );
    }

    let existing_rows = client
        .query(
            "
            SELECT id, attribute_definition_id, value
            FROM relationship_attribute_values
            WHERE relationship_id = $1
            ",
            &[&relationship_id],
        )
        .await
        .map_err(|e| {
            format!("Could not load existing PostgreSQL experiment relationship attributes: {e}")
        })?;

    let mut existing_values_by_definition_id: HashMap<String, (String, String)> = HashMap::new();
    for row in existing_rows {
        existing_values_by_definition_id.insert(row.get(1), (row.get(0), row.get(2)));
    }

    let allowed_definition_ids: HashSet<String> = definitions_by_id.keys().cloned().collect();
    for (definition_id, (existing_value_id, existing_value)) in &existing_values_by_definition_id {
        if !allowed_definition_ids.contains(definition_id) {
            append_postgres_experiment_attribute_value_history_for_client(
                client,
                "relationship",
                relationship_id,
                definition_id,
                Some(existing_value_id),
                existing_value,
                "",
                "definition_removed",
                change_context,
            )
            .await?;
            client
                .execute(
                    "
                    DELETE FROM relationship_attribute_values
                    WHERE id = $1
                    ",
                    &[existing_value_id],
                )
                .await
                .map_err(|e| {
                    format!(
                        "Could not remove PostgreSQL experiment relationship attribute value: {e}"
                    )
                })?;
        }
    }

    let mut seen_definition_ids = HashSet::new();
    for input in attribute_values {
        let attribute_definition_id = input.attribute_definition_id.trim().to_string();
        if attribute_definition_id.is_empty() {
            return Err("Relationship attribute definition id is required.".to_string());
        }
        if !seen_definition_ids.insert(attribute_definition_id.clone()) {
            return Err(
                "Relationship attribute values must not repeat the same attribute definition."
                    .to_string(),
            );
        }

        let Some((data_type, options)) = definitions_by_id.get(&attribute_definition_id) else {
            return Err("One of the relationship attributes no longer exists.".to_string());
        };

        let value = input.value.trim().to_string();
        if data_type == "categorical"
            && !value.is_empty()
            && !options.iter().any(|option| option == &value)
        {
            return Err(format!(
                "Relationship attribute value \"{value}\" is not one of the allowed options."
            ));
        }

        if let Some((existing_value_id, existing_value)) =
            existing_values_by_definition_id.get(&attribute_definition_id)
        {
            if value.is_empty() {
                append_postgres_experiment_attribute_value_history_for_client(
                    client,
                    "relationship",
                    relationship_id,
                    &attribute_definition_id,
                    Some(existing_value_id),
                    existing_value,
                    "",
                    "clear",
                    change_context,
                )
                .await?;
                client
                    .execute(
                        "
                        DELETE FROM relationship_attribute_values
                        WHERE id = $1
                        ",
                        &[existing_value_id],
                    )
                    .await
                    .map_err(|e| format!("Could not remove PostgreSQL experiment relationship attribute value: {e}"))?;
            } else {
                append_postgres_experiment_attribute_value_history_for_client(
                    client,
                    "relationship",
                    relationship_id,
                    &attribute_definition_id,
                    Some(existing_value_id),
                    existing_value,
                    &value,
                    "set",
                    change_context,
                )
                .await?;
                client
                    .execute(
                        "
                        UPDATE relationship_attribute_values
                        SET value = $2,
                            updated_at = NOW()
                        WHERE id = $1
                        ",
                        &[existing_value_id, &value],
                    )
                    .await
                    .map_err(|e| format!("Could not update PostgreSQL experiment relationship attribute value: {e}"))?;
            }
        } else if !value.is_empty() {
            let value_id = generate_identifier();
            append_postgres_experiment_attribute_value_history_for_client(
                client,
                "relationship",
                relationship_id,
                &attribute_definition_id,
                Some(&value_id),
                "",
                &value,
                "set",
                change_context,
            )
            .await?;
            client
                .execute(
                    "
                    INSERT INTO relationship_attribute_values (id, relationship_id, attribute_definition_id, value)
                    VALUES ($1, $2, $3, $4)
                    ",
                    &[&value_id, &relationship_id, &attribute_definition_id, &value],
                )
                .await
                .map_err(|e| format!("Could not create PostgreSQL experiment relationship attribute value: {e}"))?;
        }
    }

    Ok(())
}

#[tauri::command]
async fn list_postgres_experiment_sources_command(
    app: tauri::AppHandle,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
    project_id: String,
) -> Result<Vec<PostgresExperimentSource>, String> {
    let project_id = project_id.trim().to_string();
    if project_id.is_empty() {
        return Err("Project id is required.".to_string());
    }

    let project = load_postgres_experiment_project_record(&app, &project_id).await?;
    let _session =
        require_postgres_experiment_project_access(&app, Some(&runtime_auth_state), &project)
            .await?;
    ensure_postgres_experiment_project_schema(&app, &project.database_name).await?;
    let (client, connection_task) = connect_postgres_database(&app, &project.database_name).await?;
    let sources = load_postgres_experiment_sources_for_client(&client, &project_id).await?;
    connection_task.abort();
    Ok(sources)
}

