#[tauri::command]
async fn create_postgres_experiment_memo_command(
    app: tauri::AppHandle,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
    request: CreatePostgresExperimentMemoRequest,
) -> Result<PostgresExperimentMemo, String> {
    let project_id = request.project_id.trim().to_string();
    if project_id.is_empty() {
        return Err("Project id is required.".to_string());
    }

    let title = request.title.trim().to_string();
    if title.is_empty() {
        return Err("Memo title is required.".to_string());
    }

    let project = load_postgres_experiment_project_record(&app, &project_id).await?;
    let session = require_postgres_experiment_project_annotation_management(
        &app,
        Some(&runtime_auth_state),
        &project,
    )
    .await?;
    ensure_postgres_experiment_project_schema(&app, &project.database_name).await?;
    let (mut client, connection_task) =
        connect_postgres_database(&app, &project.database_name).await?;

    let source_ids = normalize_postgres_experiment_identifier_list(request.source_ids);
    let annotation_ids = normalize_postgres_experiment_identifier_list(request.annotation_ids);
    let code_ids = normalize_postgres_experiment_identifier_list(request.code_ids);
    let object_ids = normalize_postgres_experiment_identifier_list(request.object_ids);
    validate_postgres_experiment_source_ids_for_client(&client, &source_ids).await?;
    validate_postgres_experiment_annotation_ids_for_client(&client, &annotation_ids).await?;
    if !code_ids.is_empty() {
        validate_postgres_experiment_annotation_code_ids_for_client(&client, &code_ids).await?;
    }
    validate_postgres_experiment_object_ids_for_client(&client, &object_ids).await?;
    let created_by_project_user_id =
        resolve_postgres_experiment_project_user_id_for_session(&client, &session).await?;
    let memo_id = generate_identifier();
    let body = request.body.unwrap_or_default();

    let transaction = client
        .transaction()
        .await
        .map_err(|e| format!("Could not start PostgreSQL experiment memo transaction: {e}"))?;
    transaction
        .execute(
            "
            INSERT INTO memos (id, title, body, created_by_project_user_id)
            VALUES ($1, $2, $3, $4)
            ",
            &[&memo_id, &title, &body, &created_by_project_user_id],
        )
        .await
        .map_err(|e| format!("Could not create PostgreSQL experiment memo: {e}"))?;
    for source_id in &source_ids {
        transaction
            .execute(
                "INSERT INTO memo_sources (memo_id, source_id) VALUES ($1, $2)",
                &[&memo_id, source_id],
            )
            .await
            .map_err(|e| format!("Could not create PostgreSQL experiment memo-source link: {e}"))?;
    }
    for annotation_id in &annotation_ids {
        transaction
            .execute(
                "INSERT INTO memo_annotations (memo_id, annotation_id) VALUES ($1, $2)",
                &[&memo_id, annotation_id],
            )
            .await
            .map_err(|e| {
                format!("Could not create PostgreSQL experiment memo-annotation link: {e}")
            })?;
    }
    for code_id in &code_ids {
        transaction
            .execute(
                "INSERT INTO memo_codes (memo_id, code_id) VALUES ($1, $2)",
                &[&memo_id, code_id],
            )
            .await
            .map_err(|e| format!("Could not create PostgreSQL experiment memo-code link: {e}"))?;
    }
    for object_id in &object_ids {
        transaction
            .execute(
                "INSERT INTO memo_objects (memo_id, object_id) VALUES ($1, $2)",
                &[&memo_id, object_id],
            )
            .await
            .map_err(|e| format!("Could not create PostgreSQL experiment memo-object link: {e}"))?;
    }
    transaction
        .commit()
        .await
        .map_err(|e| format!("Could not commit PostgreSQL experiment memo: {e}"))?;

    let memo = load_postgres_experiment_memo_for_client(&client, &project_id, &memo_id).await?;
    append_postgres_experiment_project_log_for_client(
        &client,
        &project_id,
        &session,
        "memo.create",
        &format!("Created memo \"{}\"", memo.title),
        Some(&memo.id),
        Some(serde_json::json!({
            "title": memo.title,
            "documentCount": memo.source_ids.len(),
            "codeCount": memo.code_ids.len(),
        })),
    )
    .await?;
    emit_postgres_experiment_project_change(&app, &project_id, "memo", &memo_id, "created");
    connection_task.abort();
    Ok(memo)
}

#[tauri::command]
async fn update_postgres_experiment_memo_command(
    app: tauri::AppHandle,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
    request: UpdatePostgresExperimentMemoRequest,
) -> Result<PostgresExperimentMemo, String> {
    let project_id = request.project_id.trim().to_string();
    if project_id.is_empty() {
        return Err("Project id is required.".to_string());
    }

    let memo_id = request.memo_id.trim().to_string();
    if memo_id.is_empty() {
        return Err("Memo id is required.".to_string());
    }

    let title = request.title.trim().to_string();
    if title.is_empty() {
        return Err("Memo title is required.".to_string());
    }

    let project = load_postgres_experiment_project_record(&app, &project_id).await?;
    let session = require_postgres_experiment_project_annotation_management(
        &app,
        Some(&runtime_auth_state),
        &project,
    )
    .await?;
    ensure_postgres_experiment_project_schema(&app, &project.database_name).await?;
    let (mut client, connection_task) =
        connect_postgres_database(&app, &project.database_name).await?;

    let source_ids = normalize_postgres_experiment_identifier_list(request.source_ids);
    let annotation_ids = normalize_postgres_experiment_identifier_list(request.annotation_ids);
    let code_ids = normalize_postgres_experiment_identifier_list(request.code_ids);
    let object_ids = normalize_postgres_experiment_identifier_list(request.object_ids);
    validate_postgres_experiment_source_ids_for_client(&client, &source_ids).await?;
    validate_postgres_experiment_annotation_ids_for_client(&client, &annotation_ids).await?;
    if !code_ids.is_empty() {
        validate_postgres_experiment_annotation_code_ids_for_client(&client, &code_ids).await?;
    }
    validate_postgres_experiment_object_ids_for_client(&client, &object_ids).await?;
    let body = request.body.unwrap_or_default();

    let transaction = client
        .transaction()
        .await
        .map_err(|e| format!("Could not start PostgreSQL experiment memo transaction: {e}"))?;
    let updated_count = transaction
        .execute(
            "
            UPDATE memos
            SET title = $2,
                body = $3,
                updated_at = NOW()
            WHERE id = $1
            ",
            &[&memo_id, &title, &body],
        )
        .await
        .map_err(|e| format!("Could not update PostgreSQL experiment memo: {e}"))?;
    if updated_count == 0 {
        connection_task.abort();
        return Err("The selected memo could not be found.".to_string());
    }
    transaction
        .execute("DELETE FROM memo_sources WHERE memo_id = $1", &[&memo_id])
        .await
        .map_err(|e| format!("Could not replace PostgreSQL experiment memo sources: {e}"))?;
    transaction
        .execute(
            "DELETE FROM memo_annotations WHERE memo_id = $1",
            &[&memo_id],
        )
        .await
        .map_err(|e| format!("Could not replace PostgreSQL experiment memo annotations: {e}"))?;
    transaction
        .execute("DELETE FROM memo_codes WHERE memo_id = $1", &[&memo_id])
        .await
        .map_err(|e| format!("Could not replace PostgreSQL experiment memo codes: {e}"))?;
    transaction
        .execute("DELETE FROM memo_objects WHERE memo_id = $1", &[&memo_id])
        .await
        .map_err(|e| format!("Could not replace PostgreSQL experiment memo objects: {e}"))?;
    for source_id in &source_ids {
        transaction
            .execute(
                "INSERT INTO memo_sources (memo_id, source_id) VALUES ($1, $2)",
                &[&memo_id, source_id],
            )
            .await
            .map_err(|e| format!("Could not create PostgreSQL experiment memo-source link: {e}"))?;
    }
    for annotation_id in &annotation_ids {
        transaction
            .execute(
                "INSERT INTO memo_annotations (memo_id, annotation_id) VALUES ($1, $2)",
                &[&memo_id, annotation_id],
            )
            .await
            .map_err(|e| {
                format!("Could not create PostgreSQL experiment memo-annotation link: {e}")
            })?;
    }
    for code_id in &code_ids {
        transaction
            .execute(
                "INSERT INTO memo_codes (memo_id, code_id) VALUES ($1, $2)",
                &[&memo_id, code_id],
            )
            .await
            .map_err(|e| format!("Could not create PostgreSQL experiment memo-code link: {e}"))?;
    }
    for object_id in &object_ids {
        transaction
            .execute(
                "INSERT INTO memo_objects (memo_id, object_id) VALUES ($1, $2)",
                &[&memo_id, object_id],
            )
            .await
            .map_err(|e| format!("Could not create PostgreSQL experiment memo-object link: {e}"))?;
    }
    transaction
        .commit()
        .await
        .map_err(|e| format!("Could not commit PostgreSQL experiment memo update: {e}"))?;

    let memo = load_postgres_experiment_memo_for_client(&client, &project_id, &memo_id).await?;
    append_postgres_experiment_project_log_for_client(
        &client,
        &project_id,
        &session,
        "memo.update",
        &format!("Updated memo \"{}\"", memo.title),
        Some(&memo.id),
        Some(serde_json::json!({
            "title": memo.title,
            "changedFields": ["title", "body", "source_ids", "annotation_ids", "code_ids", "object_ids"],
        })),
    ).await?;
    emit_postgres_experiment_project_change(&app, &project_id, "memo", &memo_id, "updated");
    connection_task.abort();
    Ok(memo)
}

#[tauri::command]
async fn delete_postgres_experiment_memo_command(
    app: tauri::AppHandle,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
    project_id: String,
    memo_id: String,
) -> Result<(), String> {
    let project_id = project_id.trim().to_string();
    if project_id.is_empty() {
        return Err("Project id is required.".to_string());
    }

    let memo_id = memo_id.trim().to_string();
    if memo_id.is_empty() {
        return Err("Memo id is required.".to_string());
    }

    let project = load_postgres_experiment_project_record(&app, &project_id).await?;
    let session = require_postgres_experiment_project_annotation_management(
        &app,
        Some(&runtime_auth_state),
        &project,
    )
    .await?;
    ensure_postgres_experiment_project_schema(&app, &project.database_name).await?;
    let (client, connection_task) = connect_postgres_database(&app, &project.database_name).await?;
    let deleted_title = client
        .query_opt("SELECT title FROM memos WHERE id = $1", &[&memo_id])
        .await
        .map_err(|e| format!("Could not inspect PostgreSQL experiment memo before deletion: {e}"))?
        .map(|row| row.get::<usize, String>(0));
    let deleted_count = client
        .execute("DELETE FROM memos WHERE id = $1", &[&memo_id])
        .await
        .map_err(|e| format!("Could not delete PostgreSQL experiment memo: {e}"))?;

    if deleted_count == 0 {
        connection_task.abort();
        return Err("The selected memo could not be found.".to_string());
    }

    append_postgres_experiment_project_log_for_client(
        &client,
        &project_id,
        &session,
        "memo.delete",
        "Deleted a memo",
        Some(&memo_id),
        Some(serde_json::json!({
            "title": deleted_title,
        })),
    )
    .await?;
    emit_postgres_experiment_project_change(&app, &project_id, "memo", &memo_id, "deleted");
    connection_task.abort();
    Ok(())
}

fn normalize_postgres_experiment_report_json(raw: Option<String>) -> String {
    let value = raw.unwrap_or_default();
    let trimmed = value.trim();
    if trimmed.is_empty() {
        "{}".to_string()
    } else {
        trimmed.to_string()
    }
}

fn normalize_postgres_experiment_ai_json(raw: Option<String>) -> String {
    let value = raw.unwrap_or_default();
    let trimmed = value.trim();
    if trimmed.is_empty() {
        "{}".to_string()
    } else {
        trimmed.to_string()
    }
}

fn normalize_postgres_experiment_array_json(raw: Option<String>) -> String {
    let value = raw.unwrap_or_default();
    let trimmed = value.trim();
    if trimmed.is_empty() {
        "[]".to_string()
    } else {
        trimmed.to_string()
    }
}

fn normalize_postgres_experiment_ai_job_type(value: &str) -> Option<&'static str> {
    match value.trim() {
        "project_chat" => Some("project_chat"),
        "document_processing" => Some("document_processing"),
        "attribute_suggestions" => Some("attribute_suggestions"),
        "embedding_build" => Some("embedding_build"),
        "relevant_segments_search" => Some("relevant_segments_search"),
        "code_conceptual_summary" => Some("code_conceptual_summary"),
        "most_typical_annotation" => Some("most_typical_annotation"),
        "code_decomposition" => Some("code_decomposition"),
        "code_position" => Some("code_position"),
        "code_unique_annotations" => Some("code_unique_annotations"),
        _ => None,
    }
}

fn normalize_postgres_experiment_ai_job_status(value: &str) -> Option<&'static str> {
    match value.trim() {
        "queued" => Some("queued"),
        "running" => Some("running"),
        "completed" => Some("completed"),
        "error" => Some("error"),
        _ => None,
    }
}

async fn load_postgres_experiment_ai_jobs_for_client(
    client: &tokio_postgres::Client,
    project_id: &str,
    job_type: Option<&str>,
) -> Result<Vec<PostgresExperimentAiJob>, String> {
    let rows = if let Some(job_type) = job_type {
        client
            .query(
                "
                SELECT
                    j.id,
                    j.project_id,
                    j.job_type,
                    j.status,
                    j.request_json,
                    j.result_json,
                    j.error_message,
                    j.host_message,
                    COALESCE(j.created_by_project_user_id, '') AS created_by_project_user_id,
                    COALESCE(pu.name, '') AS created_by_name,
                    j.created_at::text,
                    j.updated_at::text
                FROM ai_jobs j
                LEFT JOIN project_users pu ON pu.id = j.created_by_project_user_id
                WHERE j.project_id = $1 AND j.job_type = $2
                ORDER BY j.created_at DESC, j.id ASC
                ",
                &[&project_id, &job_type],
            )
            .await
    } else {
        client
            .query(
                "
                SELECT
                    j.id,
                    j.project_id,
                    j.job_type,
                    j.status,
                    j.request_json,
                    j.result_json,
                    j.error_message,
                    j.host_message,
                    COALESCE(j.created_by_project_user_id, '') AS created_by_project_user_id,
                    COALESCE(pu.name, '') AS created_by_name,
                    j.created_at::text,
                    j.updated_at::text
                FROM ai_jobs j
                LEFT JOIN project_users pu ON pu.id = j.created_by_project_user_id
                WHERE j.project_id = $1
                ORDER BY j.created_at DESC, j.id ASC
                ",
                &[&project_id],
            )
            .await
    }
    .map_err(|e| format!("Could not load PostgreSQL experiment AI jobs: {e}"))?;

    Ok(rows
        .into_iter()
        .map(|row| PostgresExperimentAiJob {
            id: row.get(0),
            project_id: row.get(1),
            job_type: row.get(2),
            status: row.get(3),
            request_json: row.get(4),
            result_json: row.get(5),
            error_message: row.get(6),
            host_message: row.get(7),
            created_by_project_user_id: row.get(8),
            created_by_name: row.get(9),
            created_at: row.get(10),
            updated_at: row.get(11),
        })
        .collect())
}

async fn load_postgres_experiment_ai_job_for_client(
    client: &tokio_postgres::Client,
    project_id: &str,
    job_id: &str,
) -> Result<PostgresExperimentAiJob, String> {
    let row = client
        .query_opt(
            "
            SELECT
                j.id,
                j.project_id,
                j.job_type,
                j.status,
                j.request_json,
                j.result_json,
                j.error_message,
                j.host_message,
                COALESCE(j.created_by_project_user_id, '') AS created_by_project_user_id,
                COALESCE(pu.name, '') AS created_by_name,
                j.created_at::text,
                j.updated_at::text
            FROM ai_jobs j
            LEFT JOIN project_users pu ON pu.id = j.created_by_project_user_id
            WHERE j.project_id = $1 AND j.id = $2
            ",
            &[&project_id, &job_id],
        )
        .await
        .map_err(|e| format!("Could not load PostgreSQL experiment AI job: {e}"))?
        .ok_or_else(|| "The selected AI job could not be found.".to_string())?;

    Ok(PostgresExperimentAiJob {
        id: row.get(0),
        project_id: row.get(1),
        job_type: row.get(2),
        status: row.get(3),
        request_json: row.get(4),
        result_json: row.get(5),
        error_message: row.get(6),
        host_message: row.get(7),
        created_by_project_user_id: row.get(8),
        created_by_name: row.get(9),
        created_at: row.get(10),
        updated_at: row.get(11),
    })
}

#[tauri::command]
async fn list_postgres_experiment_ai_jobs_command(
    app: tauri::AppHandle,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
    project_id: String,
    job_type: Option<String>,
) -> Result<Vec<PostgresExperimentAiJob>, String> {
    let project_id = project_id.trim().to_string();
    if project_id.is_empty() {
        return Err("Project id is required.".to_string());
    }
    let normalized_job_type = match job_type
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(value) => Some(
            normalize_postgres_experiment_ai_job_type(value)
                .ok_or_else(|| "Unsupported AI job type.".to_string())?
                .to_string(),
        ),
        None => None,
    };

    let project = load_postgres_experiment_project_record(&app, &project_id).await?;
    let _session =
        require_postgres_experiment_project_access(&app, Some(&runtime_auth_state), &project)
            .await?;
    ensure_postgres_experiment_project_schema(&app, &project.database_name).await?;
    let (client, connection_task) = connect_postgres_database(&app, &project.database_name).await?;
    let jobs = load_postgres_experiment_ai_jobs_for_client(
        &client,
        &project_id,
        normalized_job_type.as_deref(),
    )
    .await?;
    connection_task.abort();
    Ok(jobs)
}

