fn project_role_allows_embedding_build(role: Option<&str>) -> bool {
    matches!(role.map(str::trim), Some("owner") | Some("editor"))
}

fn build_encrypted_backup_argon2() -> Result<Argon2<'static>, String> {
    let params = Params::new(
        ENCRYPTED_BACKUP_ARGON2_MEMORY_KIB,
        ENCRYPTED_BACKUP_ARGON2_ITERATIONS,
        ENCRYPTED_BACKUP_ARGON2_PARALLELISM,
        Some(32),
    )
    .map_err(|e| e.to_string())?;
    Ok(Argon2::new(Algorithm::Argon2id, Version::V0x13, params))
}

fn derive_encrypted_backup_key(password: &[u8], salt: &[u8]) -> Result<[u8; 32], String> {
    let mut key = [0_u8; 32];
    build_encrypted_backup_argon2()?
        .hash_password_into(password, salt, &mut key)
        .map_err(|e| e.to_string())?;
    Ok(key)
}

fn encrypt_backup_payload_text(payload_json: String, password: String) -> Result<String, String> {
    let mut salt = [0_u8; ENCRYPTED_BACKUP_SALT_BYTES];
    let mut nonce_bytes = [0_u8; ENCRYPTED_BACKUP_NONCE_BYTES];
    rand::rngs::OsRng.fill_bytes(&mut salt);
    rand::rngs::OsRng.fill_bytes(&mut nonce_bytes);

    let password = Zeroizing::new(password.into_bytes());
    let key = derive_encrypted_backup_key(password.as_slice(), &salt)?;
    let cipher = Aes256Gcm::new_from_slice(&key).map_err(|e| e.to_string())?;
    let nonce = Nonce::from_slice(&nonce_bytes);
    let ciphertext = cipher
        .encrypt(nonce, payload_json.as_bytes())
        .map_err(|_| "Failed to encrypt the backup.".to_string())?;

    let envelope = EncryptedBackupEnvelope {
        kind: ENCRYPTED_BACKUP_KIND.to_string(),
        version: ENCRYPTED_BACKUP_VERSION,
        cipher: ENCRYPTED_BACKUP_CIPHER.to_string(),
        kdf: EncryptedBackupKdfSpec {
            name: ENCRYPTED_BACKUP_KDF_NAME.to_string(),
            memory_kib: ENCRYPTED_BACKUP_ARGON2_MEMORY_KIB,
            iterations: ENCRYPTED_BACKUP_ARGON2_ITERATIONS,
            parallelism: ENCRYPTED_BACKUP_ARGON2_PARALLELISM,
            salt_b64: BASE64_STANDARD.encode(salt),
        },
        nonce_b64: BASE64_STANDARD.encode(nonce_bytes),
        ciphertext_b64: BASE64_STANDARD.encode(ciphertext),
    };

    serde_json::to_string_pretty(&envelope).map_err(|e| e.to_string())
}

fn ensure_project_backup_json_shape(text: &str) -> Result<(), String> {
    let parsed: Value = serde_json::from_str(text)
        .map_err(|_| "The backup content is not valid JSON.".to_string())?;
    let object = parsed
        .as_object()
        .ok_or_else(|| "The decrypted file is not a Kanqual backup.".to_string())?;
    let kind = object
        .get("kind")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if kind != "kanqual-project-backup" {
        return Err("The decrypted file is not a Kanqual project backup.".to_string());
    }
    if !object.contains_key("payload") {
        return Err("The decrypted backup is missing its project payload.".to_string());
    }
    Ok(())
}

fn value_string_required<'a>(value: &'a Value, key: &str, label: &str) -> Result<&'a str, String> {
    value
        .get(key)
        .and_then(Value::as_str)
        .filter(|text| !text.trim().is_empty())
        .ok_or_else(|| format!("The upgrade backup is missing {label}."))
}

fn value_array_required<'a>(
    value: &'a Value,
    key: &str,
    label: &str,
) -> Result<&'a Vec<Value>, String> {
    value
        .get(key)
        .and_then(Value::as_array)
        .ok_or_else(|| format!("The upgrade backup is missing {label}."))
}

fn validate_upgrade_backup_schema_versions(
    versions: &[Value],
    label: &str,
    max_supported_version: i32,
) -> Result<(), String> {
    if versions.is_empty() {
        return Err(format!(
            "The upgrade backup has invalid {label} schema version metadata."
        ));
    }
    let mut highest_version = 0_i32;
    for version in versions {
        let version = version.as_i64().ok_or_else(|| {
            format!("The upgrade backup has invalid {label} schema version metadata.")
        })?;
        if version < 1 || version > i32::MAX as i64 {
            return Err(format!(
                "The upgrade backup has invalid {label} schema version metadata."
            ));
        }
        highest_version = highest_version.max(version as i32);
    }
    if highest_version > max_supported_version {
        return Err(format!(
            "This upgrade backup was created with a newer KanQual {label} schema and cannot be restored by this version."
        ));
    }
    Ok(())
}

fn validate_upgrade_backup_database_dump(value: &Value, label: &str) -> Result<(), String> {
    let sql = value_string_required(value, "sql", &format!("{label} SQL"))?;
    let expected_sha256 = value_string_required(value, "sha256", &format!("{label} checksum"))?;
    let actual_sha256 = sha256_hex(sql.as_bytes());
    if actual_sha256 != expected_sha256 {
        return Err(format!(
            "The upgrade backup {label} checksum does not match its SQL payload."
        ));
    }
    Ok(())
}

fn validate_upgrade_backup_storage_file(value: &Value) -> Result<(), String> {
    let relative_path = value_string_required(value, "relativePath", "a storage file path")?;
    let _ = safe_backup_relative_path(relative_path)?;
    let bytes_b64 = value_string_required(value, "bytesB64", "a storage file payload")?;
    let expected_sha256 =
        value_string_required(value, "checksumSha256", "a storage file checksum")?;
    let expected_size = value
        .get("sizeBytes")
        .and_then(Value::as_u64)
        .ok_or_else(|| "The upgrade backup is missing a storage file size.".to_string())?;
    let bytes = BASE64_STANDARD.decode(bytes_b64).map_err(|_| {
        "A storage file payload in the upgrade backup is not valid base64.".to_string()
    })?;
    if bytes.len() as u64 != expected_size {
        return Err(
            "A storage file payload in the upgrade backup does not match its recorded size."
                .to_string(),
        );
    }
    if sha256_hex(&bytes) != expected_sha256 {
        return Err(
            "A storage file payload in the upgrade backup does not match its checksum.".to_string(),
        );
    }
    Ok(())
}

fn validate_upgrade_backup_project_manifest(
    project: &Value,
    project_dumps: &std::collections::HashMap<String, String>,
    storage_files: &[Value],
) -> Result<(), String> {
    let database_name = value_string_required(project, "databaseName", "a project database name")?;
    let expected_dump_sha256 = value_string_required(
        project,
        "databaseDumpSha256",
        "a project database dump checksum",
    )?;
    let actual_dump_sha256 = project_dumps.get(database_name).ok_or_else(|| {
        format!("The upgrade backup is missing a dump for project database {database_name}.")
    })?;
    if actual_dump_sha256 != expected_dump_sha256 {
        return Err(format!(
            "The upgrade backup project manifest checksum does not match project database {database_name}."
        ));
    }
    let schema_versions =
        value_array_required(project, "schemaVersions", "project schema versions")?;
    validate_upgrade_backup_schema_versions(
        schema_versions,
        &format!("project {database_name}"),
        POSTGRES_EXPERIMENT_PROJECT_SCHEMA_VERSION,
    )?;

    let project_id = value_string_required(project, "id", "a project id")?;
    let expected_file_count = project
        .get("storageFileCount")
        .and_then(Value::as_u64)
        .ok_or_else(|| "The upgrade backup is missing a project storage file count.".to_string())?;
    let expected_storage_bytes = project
        .get("storageBytes")
        .and_then(Value::as_u64)
        .ok_or_else(|| "The upgrade backup is missing a project storage byte count.".to_string())?;
    let expected_storage_sha256 =
        value_string_required(project, "storageSha256", "a project storage checksum")?;
    let project_files = storage_files
        .iter()
        .filter(|file| backup_value_string(file, "projectId") == project_id)
        .collect::<Vec<_>>();
    if project_files.len() as u64 != expected_file_count {
        return Err(format!(
            "The upgrade backup project {database_name} storage file count does not match its manifest."
        ));
    }
    let storage_bytes = project_files.iter().try_fold(0_u64, |total, file| {
        file.get("sizeBytes")
            .and_then(Value::as_u64)
            .map(|size| total + size)
            .ok_or_else(|| "The upgrade backup is missing a storage file size.".to_string())
    })?;
    if storage_bytes != expected_storage_bytes {
        return Err(format!(
            "The upgrade backup project {database_name} storage byte count does not match its manifest."
        ));
    }
    let storage_sha256 = storage_collection_sha256(project_files.iter().copied());
    if storage_sha256 != expected_storage_sha256 {
        return Err(format!(
            "The upgrade backup project {database_name} storage checksum does not match its manifest."
        ));
    }
    Ok(())
}

fn ensure_upgrade_backup_json_shape(text: &str) -> Result<(), String> {
    let parsed: Value = serde_json::from_str(text)
        .map_err(|_| "The decrypted upgrade backup is not valid JSON.".to_string())?;
    let object = parsed
        .as_object()
        .ok_or_else(|| "The decrypted file is not a KanQual upgrade backup.".to_string())?;
    if object.get("kind").and_then(Value::as_str) != Some("kanqual-full-backend-upgrade-backup") {
        return Err("The selected file is not a KanQual full backend upgrade backup.".to_string());
    }
    if object.get("version").and_then(Value::as_u64) != Some(1) {
        return Err("This KanQual upgrade backup format is not supported.".to_string());
    }
    let manifest = object
        .get("manifest")
        .and_then(Value::as_object)
        .ok_or_else(|| "The upgrade backup is missing manifest metadata.".to_string())?;
    for key in [
        "kanqualVersion",
        "postgresVersion",
        "backupFormatVersion",
        "controlDatabase",
        "controlDumpSha256",
        "backupReason",
        "platform",
        "architecture",
    ] {
        if !manifest
            .get(key)
            .and_then(Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
        {
            return Err(format!("The upgrade backup manifest is missing {key}."));
        }
    }
    let control_schema_versions = manifest
        .get("controlSchemaVersions")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            "The upgrade backup manifest is missing control schema versions.".to_string()
        })?;
    validate_upgrade_backup_schema_versions(
        control_schema_versions,
        "control",
        POSTGRES_EXPERIMENT_CONTROL_SCHEMA_VERSION,
    )?;
    let control_dump = object
        .get("controlDump")
        .ok_or_else(|| "The upgrade backup is missing the control database dump.".to_string())?;
    validate_upgrade_backup_database_dump(control_dump, "control database dump")?;
    if value_string_required(control_dump, "sha256", "control dump checksum")?
        != manifest
            .get("controlDumpSha256")
            .and_then(Value::as_str)
            .unwrap_or_default()
    {
        return Err(
            "The upgrade backup control dump checksum does not match its manifest.".to_string(),
        );
    }

    let project_dumps = value_array_required(&parsed, "projectDumps", "project database dumps")?;
    let mut dump_checksums = std::collections::HashMap::new();
    for dump in project_dumps {
        let database_name = value_string_required(dump, "databaseName", "a project database name")?;
        validate_upgrade_backup_database_dump(
            dump,
            &format!("project database dump {database_name}"),
        )?;
        dump_checksums.insert(
            database_name.to_string(),
            value_string_required(dump, "sha256", "a project database checksum")?.to_string(),
        );
    }

    let storage_files = object
        .get("projectStorageFiles")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    for file in &storage_files {
        validate_upgrade_backup_storage_file(file)?;
    }

    let projects = value_array_required(&parsed, "projects", "project metadata")?;
    for project in projects {
        validate_upgrade_backup_project_manifest(project, &dump_checksums, &storage_files)?;
    }
    Ok(())
}

fn decrypt_encrypted_backup_payload_inner(
    encrypted_backup: &str,
    password: &str,
) -> Result<String, String> {
    decrypt_encrypted_backup_payload_text(
        encrypted_backup,
        password,
        Some(ensure_project_backup_json_shape),
    )
}

fn decrypt_encrypted_backup_payload_text(
    encrypted_backup: &str,
    password: &str,
    validate: Option<fn(&str) -> Result<(), String>>,
) -> Result<String, String> {
    let envelope: EncryptedBackupEnvelope = serde_json::from_str(encrypted_backup)
        .map_err(|_| "The selected file is not a valid encrypted Kanqual backup.".to_string())?;
    if envelope.kind != ENCRYPTED_BACKUP_KIND || envelope.version != ENCRYPTED_BACKUP_VERSION {
        return Err("This encrypted backup uses an unsupported Kanqual backup format.".to_string());
    }
    if envelope.cipher != ENCRYPTED_BACKUP_CIPHER {
        return Err("This encrypted backup uses an unsupported encryption algorithm.".to_string());
    }
    if envelope.kdf.name != ENCRYPTED_BACKUP_KDF_NAME {
        return Err("This encrypted backup uses an unsupported key derivation method.".to_string());
    }

    let salt = BASE64_STANDARD
        .decode(envelope.kdf.salt_b64)
        .map_err(|_| "The encrypted backup salt is invalid.".to_string())?;
    let nonce_bytes = BASE64_STANDARD
        .decode(envelope.nonce_b64)
        .map_err(|_| "The encrypted backup nonce is invalid.".to_string())?;
    let ciphertext = BASE64_STANDARD
        .decode(envelope.ciphertext_b64)
        .map_err(|_| "The encrypted backup ciphertext is invalid.".to_string())?;

    if nonce_bytes.len() != ENCRYPTED_BACKUP_NONCE_BYTES {
        return Err("The encrypted backup nonce length is invalid.".to_string());
    }

    let password = Zeroizing::new(password.as_bytes().to_vec());
    let key = derive_encrypted_backup_key(password.as_slice(), &salt)?;
    let cipher = Aes256Gcm::new_from_slice(&key).map_err(|e| e.to_string())?;
    let nonce = Nonce::from_slice(&nonce_bytes);
    let plaintext = cipher
        .decrypt(nonce, ciphertext.as_ref())
        .map_err(|_| "Incorrect password or corrupted encrypted backup.".to_string())?;
    let plaintext = String::from_utf8(plaintext)
        .map_err(|_| "The decrypted backup is not valid UTF-8 text.".to_string())?;
    if let Some(validate) = validate {
        validate(&plaintext)?;
    }
    Ok(plaintext)
}

#[tauri::command]
fn encrypt_project_backup(request: EncryptProjectBackupRequest) -> Result<String, String> {
    if request.password.trim().is_empty() {
        return Err("Please enter a password for the encrypted backup.".to_string());
    }
    ensure_project_backup_json_shape(&request.backup_json)?;
    encrypt_backup_payload_text(request.backup_json, request.password)
}

#[tauri::command]
fn decrypt_project_backup_payload(request: DecryptProjectBackupRequest) -> Result<String, String> {
    decrypt_encrypted_backup_payload_inner(&request.encrypted_backup, &request.password)
}

#[tauri::command]
fn decrypt_project_backup_preview(
    request: DecryptProjectBackupRequest,
) -> Result<DecryptedProjectBackupPreview, String> {
    let plaintext =
        decrypt_encrypted_backup_payload_inner(&request.encrypted_backup, &request.password)?;
    let parsed: Value = serde_json::from_str(&plaintext)
        .map_err(|_| "The decrypted backup is not valid JSON.".to_string())?;
    let object = parsed
        .as_object()
        .ok_or_else(|| "The decrypted file is not a Kanqual backup.".to_string())?;

    Ok(DecryptedProjectBackupPreview {
        project_name: object
            .get("projectName")
            .and_then(Value::as_str)
            .filter(|value| !value.trim().is_empty())
            .unwrap_or("Imported Project")
            .to_string(),
        created_at: object
            .get("createdAt")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        version: object
            .get("version")
            .and_then(Value::as_u64)
            .and_then(|value| u32::try_from(value).ok()),
    })
}

fn run_pg_dump_command(
    pg_dump_path: &Path,
    host: &str,
    port: u16,
    user: &str,
    password: &str,
    database: &str,
) -> Result<String, String> {
    let output = Command::new(pg_dump_path)
        .env("PGPASSWORD", password)
        .args([
            "-h",
            host,
            "-p",
            &port.to_string(),
            "-U",
            user,
            "-d",
            database,
            "--format=plain",
            "--no-owner",
            "--no-privileges",
            "--clean",
            "--if-exists",
        ])
        .output()
        .map_err(|e| format!("Failed to run pg_dump at {}: {e}", pg_dump_path.display()))?;

    if output.status.success() {
        Ok(String::from_utf8_lossy(&output.stdout).to_string())
    } else {
        Err(String::from_utf8_lossy(&output.stderr).trim().to_string())
    }
}

fn run_psql_script_with_binary(
    psql_path: &Path,
    host: &str,
    port: u16,
    user: &str,
    password: &str,
    database: &str,
    sql: &str,
) -> Result<(), String> {
    let mut child = Command::new(psql_path)
        .env("PGPASSWORD", password)
        .args([
            "-v",
            "ON_ERROR_STOP=1",
            "-h",
            host,
            "-p",
            &port.to_string(),
            "-U",
            user,
            "-d",
            database,
        ])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("Failed to run psql at {}: {e}", psql_path.display()))?;

    if let Some(mut stdin) = child.stdin.take() {
        stdin
            .write_all(sql.as_bytes())
            .map_err(|e| format!("Could not send restore SQL to psql: {e}"))?;
    }

    let output = child
        .wait_with_output()
        .map_err(|e| format!("Could not wait for psql restore to finish: {e}"))?;
    if output.status.success() {
        Ok(())
    } else {
        Err(String::from_utf8_lossy(&output.stderr).trim().to_string())
    }
}

fn backup_value_string(value: &Value, key: &str) -> String {
    value
        .get(key)
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string()
}

fn system_time_to_ms(value: SystemTime) -> u64 {
    value
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0)
}

fn upgrade_backup_diagnostics_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    let paths = bundled_postgres::resolve_paths(app)?;
    Ok(Path::new(&paths.upgrade_backups_dir).join(UPGRADE_BACKUP_DIAGNOSTICS_FILE))
}

fn read_upgrade_backup_diagnostics_manifest(
    app: &tauri::AppHandle,
) -> PostgresUpgradeBackupDiagnosticsManifest {
    let Ok(path) = upgrade_backup_diagnostics_path(app) else {
        return PostgresUpgradeBackupDiagnosticsManifest::default();
    };
    let Ok(text) = fs::read_to_string(path) else {
        return PostgresUpgradeBackupDiagnosticsManifest::default();
    };
    serde_json::from_str(&text).unwrap_or_default()
}

fn write_upgrade_backup_diagnostics_manifest(
    app: &tauri::AppHandle,
    manifest: &PostgresUpgradeBackupDiagnosticsManifest,
) -> Result<(), String> {
    let path = upgrade_backup_diagnostics_path(app)?;
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| {
            format!(
                "Could not create upgrade backup diagnostics folder at {}: {e}",
                parent.display()
            )
        })?;
    }
    let text = serde_json::to_string_pretty(manifest).map_err(|e| e.to_string())?;
    fs::write(&path, text).map_err(|e| {
        format!(
            "Could not write upgrade backup diagnostics at {}: {e}",
            path.display()
        )
    })
}

fn record_upgrade_backup_diagnostics(
    app: &tauri::AppHandle,
    result: &PostgresUpgradeBackupResult,
) -> Result<(), String> {
    let path = PathBuf::from(&result.path);
    let modified_at_ms = fs::metadata(&path)
        .and_then(|metadata| metadata.modified())
        .map(system_time_to_ms)
        .unwrap_or(result.created_at_ms);
    let entry = PostgresUpgradeBackupDiagnosticsEntry {
        path: result.path.clone(),
        file_name: path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("KanQual upgrade backup")
            .to_string(),
        created_at_ms: result.created_at_ms,
        modified_at_ms,
        kanqual_version: result.kanqual_version.clone(),
        postgres_version: result.postgres_version.clone(),
        project_count: result.project_count,
        storage_file_count: result.storage_file_count,
        bytes: result.bytes,
        source: "created".to_string(),
        exists: path.is_file(),
    };
    let mut manifest = read_upgrade_backup_diagnostics_manifest(app);
    manifest
        .entries
        .retain(|existing| existing.path != entry.path);
    manifest.entries.insert(0, entry);
    manifest
        .entries
        .sort_by(|left, right| right.created_at_ms.cmp(&left.created_at_ms));
    manifest.entries.truncate(100);
    write_upgrade_backup_diagnostics_manifest(app, &manifest)
}

fn storage_collection_sha256<'a>(files: impl Iterator<Item = &'a Value>) -> String {
    let mut parts = files
        .map(|file| {
            format!(
                "{}\n{}\n{}\n{}\n",
                backup_value_string(file, "projectId"),
                backup_value_string(file, "relativePath"),
                file.get("sizeBytes").and_then(Value::as_u64).unwrap_or(0),
                backup_value_string(file, "checksumSha256")
            )
        })
        .collect::<Vec<_>>();
    parts.sort();
    sha256_hex(parts.join("").as_bytes())
}

fn storage_collection_sha256_from_records(files: &[PostgresUpgradeBackupStorageFile]) -> String {
    let mut parts = files
        .iter()
        .map(|file| {
            format!(
                "{}\n{}\n{}\n{}\n",
                file.project_id, file.relative_path, file.size_bytes, file.checksum_sha256
            )
        })
        .collect::<Vec<_>>();
    parts.sort();
    sha256_hex(parts.join("").as_bytes())
}

async fn load_postgres_schema_versions_for_client<C>(client: &C) -> Result<Vec<i32>, String>
where
    C: GenericClient + Sync,
{
    let exists = client
        .query_opt(
            "SELECT to_regclass('public.app_schema_migrations')::text",
            &[],
        )
        .await
        .map_err(|e| format!("Could not inspect schema migrations table: {e}"))?
        .and_then(|row| row.get::<usize, Option<String>>(0))
        .is_some();
    if !exists {
        return Err("Schema migration metadata is missing.".to_string());
    }
    let rows = client
        .query(
            "SELECT version FROM app_schema_migrations ORDER BY version",
            &[],
        )
        .await
        .map_err(|e| format!("Could not load schema migration metadata: {e}"))?;
    let versions = rows
        .into_iter()
        .map(|row| row.get::<usize, i32>(0))
        .collect::<Vec<_>>();
    if versions.is_empty() {
        return Err("Schema migration metadata is empty.".to_string());
    }
    Ok(versions)
}

fn safe_backup_relative_path(value: &str) -> Result<PathBuf, String> {
    let path = Path::new(value);
    if path.is_absolute() {
        return Err("Backup storage file path must be relative.".to_string());
    }
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::Normal(part) => normalized.push(part),
            std::path::Component::CurDir => {}
            _ => return Err("Backup storage file path is not safe to restore.".to_string()),
        }
    }
    if normalized.as_os_str().is_empty() {
        return Err("Backup storage file path is empty.".to_string());
    }
    Ok(normalized)
}

fn collect_postgres_upgrade_backup_storage_files(
    project_id: &str,
    root: &Path,
) -> Result<Vec<PostgresUpgradeBackupStorageFile>, String> {
    fn visit(
        project_id: &str,
        root: &Path,
        path: &Path,
        files: &mut Vec<PostgresUpgradeBackupStorageFile>,
    ) -> Result<(), String> {
        if !path.exists() {
            return Ok(());
        }
        for entry in
            fs::read_dir(path).map_err(|e| format!("Could not read project storage: {e}"))?
        {
            let entry = entry.map_err(|e| format!("Could not read project storage entry: {e}"))?;
            let entry_path = entry.path();
            let metadata = entry
                .metadata()
                .map_err(|e| format!("Could not read project storage metadata: {e}"))?;
            if metadata.is_dir() {
                visit(project_id, root, &entry_path, files)?;
            } else if metadata.is_file() {
                let relative_path = entry_path
                    .strip_prefix(root)
                    .map_err(|e| format!("Could not normalize project storage path: {e}"))?
                    .to_string_lossy()
                    .replace('\\', "/");
                let mut bytes = Vec::with_capacity(metadata.len() as usize);
                fs::File::open(&entry_path)
                    .map_err(|e| format!("Could not open project storage file: {e}"))?
                    .read_to_end(&mut bytes)
                    .map_err(|e| format!("Could not read project storage file: {e}"))?;
                let size_bytes = bytes.len() as u64;
                let checksum_sha256 = sha256_hex(&bytes);
                files.push(PostgresUpgradeBackupStorageFile {
                    project_id: project_id.to_string(),
                    relative_path,
                    size_bytes,
                    checksum_sha256,
                    bytes_b64: BASE64_STANDARD.encode(bytes),
                });
            }
        }
        Ok(())
    }

    let mut files = Vec::new();
    visit(project_id, root, root, &mut files)?;
    files.sort_by(|left, right| left.relative_path.cmp(&right.relative_path));
    Ok(files)
}

#[tauri::command]
async fn create_postgres_experiment_upgrade_backup_command(
    app: tauri::AppHandle,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
    request: CreatePostgresUpgradeBackupRequest,
) -> Result<PostgresUpgradeBackupResult, String> {
    if request.admin_password.trim().is_empty() {
        return Err("Enter the administrator password to create an upgrade backup.".to_string());
    }

    let session = require_postgres_experiment_auth_session(&app, Some(&runtime_auth_state)).await?;
    if session.auth_kind != "postgres_admin" {
        return Err(
            "Sign in as the PostgreSQL administrator before creating an upgrade backup."
                .to_string(),
        );
    }

    ensure_postgres_experiment_control_schema(&app).await?;

    let identity = load_or_create_postgres_bootstrap_identity(&app)?;
    let config = load_postgres_runtime_config(&app)?;
    let bundled_paths = bundled_postgres::resolve_paths(&app)?;
    let pg_dump_path = PathBuf::from(&bundled_paths.pg_dump_binary);
    let psql_path = PathBuf::from(&bundled_paths.psql_binary);
    if !pg_dump_path.is_file() {
        return Err("Bundled PostgreSQL pg_dump binary is missing.".to_string());
    }

    let postgres_version = run_psql_command_with_binary(
        &psql_path,
        &config.host,
        config.port,
        &identity.superuser_name,
        &request.admin_password,
        &identity.app_database,
        "SELECT version()",
    )?;

    let (client, connection_task) = connect_postgres_runtime(&app).await?;
    let rows = client
        .query(
            "
            SELECT id, database_name, storage_path, creation_source, active, disabled_at::text, created_at::text, updated_at::text, COALESCE(to_jsonb(projects)->>'created_by_username', '')
            FROM projects
            ORDER BY created_at ASC, id ASC
            ",
            &[],
        )
        .await
        .map_err(|e| format!("Could not load projects for upgrade backup: {e}"))?;
    let control_schema_versions = load_postgres_schema_versions_for_client(&*client).await?;
    connection_task.abort();

    let mut projects = Vec::with_capacity(rows.len());
    for row in rows {
        let registry = PostgresExperimentProjectRegistryRecord {
            id: row.get(0),
            database_name: row.get(1),
            storage_path: row.get(2),
            creation_source: row.get(3),
            active: row.get(4),
            disabled_at: row.get(5),
            created_at: row.get(6),
            updated_at: row.get(7),
            created_by_username: row.get(8),
        };
        projects.push(load_postgres_experiment_project_from_registry(&app, registry).await?);
    }

    let control_dump = run_pg_dump_command(
        &pg_dump_path,
        &config.host,
        config.port,
        &identity.superuser_name,
        &request.admin_password,
        &identity.app_database,
    )?;
    let control_dump_sha256 = sha256_hex(control_dump.as_bytes());

    let mut project_dumps = Vec::with_capacity(projects.len());
    let mut project_manifest = Vec::with_capacity(projects.len());
    let mut storage_files = Vec::new();
    for project in &projects {
        let (project_client, project_connection_task) =
            connect_postgres_database(&app, &project.database_name).await?;
        let project_schema_versions =
            load_postgres_schema_versions_for_client(&*project_client).await?;
        project_connection_task.abort();

        let sql = run_pg_dump_command(
            &pg_dump_path,
            &config.host,
            config.port,
            &identity.superuser_name,
            &request.admin_password,
            &project.database_name,
        )?;
        let database_dump_sha256 = sha256_hex(sql.as_bytes());
        project_dumps.push(PostgresUpgradeBackupDatabaseDump {
            database_name: project.database_name.clone(),
            role: "project".to_string(),
            sha256: database_dump_sha256.clone(),
            sql,
        });

        let mut project_storage_files = Vec::new();
        let storage_path = PathBuf::from(&project.storage_path);
        if storage_path.exists() {
            project_storage_files =
                collect_postgres_upgrade_backup_storage_files(&project.id, &storage_path)?;
        }
        let storage_bytes = project_storage_files
            .iter()
            .map(|file| file.size_bytes)
            .sum::<u64>();
        let storage_sha256 = storage_collection_sha256_from_records(&project_storage_files);
        let storage_file_count = project_storage_files.len();
        storage_files.extend(project_storage_files);

        project_manifest.push(PostgresUpgradeBackupProjectManifest {
            id: project.id.clone(),
            name: project.name.clone(),
            database_name: project.database_name.clone(),
            storage_path: project.storage_path.clone(),
            active: project.active,
            schema_versions: project_schema_versions,
            database_dump_sha256,
            storage_file_count,
            storage_bytes,
            storage_sha256,
            created_at: project.created_at.clone(),
            updated_at: project.updated_at.clone(),
        });
    }

    let created_at_ms = current_time_ms();
    let payload = serde_json::json!({
        "kind": "kanqual-full-backend-upgrade-backup",
        "version": 1,
        "createdAtMs": created_at_ms,
        "kanqualVersion": env!("CARGO_PKG_VERSION"),
        "postgresVersion": postgres_version.clone(),
        "controlDatabase": identity.app_database.clone(),
        "manifest": {
            "backupFormatVersion": "1",
            "backupReason": "admin-upgrade-backup",
            "platform": std::env::consts::OS,
            "architecture": std::env::consts::ARCH,
            "createdAtMs": created_at_ms,
            "kanqualVersion": env!("CARGO_PKG_VERSION"),
            "postgresVersion": postgres_version.clone(),
            "controlDatabase": identity.app_database.clone(),
            "controlSchemaVersions": control_schema_versions,
            "controlDumpSha256": control_dump_sha256,
            "projectCount": project_manifest.len(),
            "storageFileCount": storage_files.len(),
        },
        "credentialPolicy": {
            "adminUsernameIncluded": false,
            "adminPasswordIncluded": false,
            "restoreRequiresNewAdminCredentials": true
        },
        "projects": project_manifest,
        "controlDump": PostgresUpgradeBackupDatabaseDump {
            database_name: identity.app_database.clone(),
            role: "control".to_string(),
            sha256: control_dump_sha256,
            sql: control_dump,
        },
        "projectDumps": project_dumps,
        "projectStorageFiles": storage_files,
    });
    let payload_json = serde_json::to_string(&payload).map_err(|e| e.to_string())?;
    ensure_upgrade_backup_json_shape(&payload_json)?;
    let encrypted = encrypt_backup_payload_text(payload_json, request.admin_password.clone())?;

    let output_path = match request
        .output_path
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(path) => PathBuf::from(path),
        None => {
            let upgrade_dir = PathBuf::from(&bundled_paths.upgrade_backups_dir);
            fs::create_dir_all(&upgrade_dir).map_err(|e| {
                format!(
                    "Could not create upgrade backup folder at {}: {e}",
                    upgrade_dir.display()
                )
            })?;
            let suffix = Alphanumeric.sample_string(&mut rand::thread_rng(), 8);
            upgrade_dir.join(format!(
                "kanqual-upgrade-backup-{created_at_ms}-{suffix}.kanqual-upgrade-backup"
            ))
        }
    };
    if let Some(parent) = output_path.parent() {
        fs::create_dir_all(parent).map_err(|e| {
            format!(
                "Could not create upgrade backup destination folder at {}: {e}",
                parent.display()
            )
        })?;
    }
    fs::write(&output_path, encrypted).map_err(|e| {
        format!(
            "Could not write upgrade backup at {}: {e}",
            output_path.display()
        )
    })?;
    let encrypted_round_trip = fs::read_to_string(&output_path).map_err(|e| {
        format!(
            "Could not verify upgrade backup at {}: {e}",
            output_path.display()
        )
    })?;
    let decrypted_round_trip = decrypt_encrypted_backup_payload_text(
        &encrypted_round_trip,
        &request.admin_password,
        Some(ensure_upgrade_backup_json_shape),
    )
    .map_err(|e| format!("Could not verify the written upgrade backup: {e}"))?;
    ensure_upgrade_backup_json_shape(&decrypted_round_trip)
        .map_err(|e| format!("Could not verify the written upgrade backup manifest: {e}"))?;
    let bytes = fs::metadata(&output_path)
        .map_err(|e| format!("Could not inspect upgrade backup file: {e}"))?
        .len();

    let result = PostgresUpgradeBackupResult {
        path: output_path.to_string_lossy().to_string(),
        created_at_ms,
        kanqual_version: env!("CARGO_PKG_VERSION").to_string(),
        postgres_version,
        control_database: identity.app_database,
        project_count: projects.len(),
        storage_file_count: payload
            .get("projectStorageFiles")
            .and_then(Value::as_array)
            .map(|items| items.len())
            .unwrap_or(0),
        bytes,
    };
    let _ = record_upgrade_backup_diagnostics(&app, &result);
    Ok(result)
}

#[tauri::command]
async fn list_postgres_experiment_upgrade_backup_diagnostics_command(
    app: tauri::AppHandle,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
) -> Result<PostgresUpgradeBackupDiagnostics, String> {
    let session = require_postgres_experiment_auth_session(&app, Some(&runtime_auth_state)).await?;
    if session.auth_kind != "postgres_admin" {
        return Err(
            "Sign in as the PostgreSQL administrator before viewing backup diagnostics."
                .to_string(),
        );
    }

    let paths = bundled_postgres::resolve_paths(&app)?;
    let upgrade_dir = PathBuf::from(&paths.upgrade_backups_dir);
    let folder_exists = upgrade_dir.is_dir();
    let manifest = read_upgrade_backup_diagnostics_manifest(&app);
    let mut entries_by_path = manifest
        .entries
        .into_iter()
        .map(|mut entry| {
            let path = PathBuf::from(&entry.path);
            entry.exists = path.is_file();
            if let Ok(metadata) = fs::metadata(&path) {
                entry.bytes = metadata.len();
                if let Ok(modified) = metadata.modified() {
                    entry.modified_at_ms = system_time_to_ms(modified);
                }
            }
            (entry.path.clone(), entry)
        })
        .collect::<HashMap<_, _>>();

    if folder_exists {
        for entry in fs::read_dir(&upgrade_dir).map_err(|e| {
            format!(
                "Could not read upgrade backup folder at {}: {e}",
                upgrade_dir.display()
            )
        })? {
            let entry =
                entry.map_err(|e| format!("Could not inspect upgrade backup folder entry: {e}"))?;
            let path = entry.path();
            if !path.is_file() {
                continue;
            }
            let file_name = path
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or_default()
                .to_string();
            if file_name == UPGRADE_BACKUP_DIAGNOSTICS_FILE
                || !file_name.ends_with(".kanqual-upgrade-backup")
            {
                continue;
            }
            let path_string = path.to_string_lossy().to_string();
            if entries_by_path.contains_key(&path_string) {
                continue;
            }
            let metadata = fs::metadata(&path).map_err(|e| {
                format!(
                    "Could not inspect upgrade backup file at {}: {e}",
                    path.display()
                )
            })?;
            let modified_at_ms = metadata.modified().map(system_time_to_ms).unwrap_or(0);
            entries_by_path.insert(
                path_string.clone(),
                PostgresUpgradeBackupDiagnosticsEntry {
                    path: path_string,
                    file_name,
                    created_at_ms: modified_at_ms,
                    modified_at_ms,
                    kanqual_version: String::new(),
                    postgres_version: String::new(),
                    project_count: 0,
                    storage_file_count: 0,
                    bytes: metadata.len(),
                    source: "folder".to_string(),
                    exists: true,
                },
            );
        }
    }

    let mut backups = entries_by_path.into_values().collect::<Vec<_>>();
    backups.sort_by(|left, right| {
        right
            .created_at_ms
            .cmp(&left.created_at_ms)
            .then_with(|| right.modified_at_ms.cmp(&left.modified_at_ms))
    });
    let last_successful_backup = backups
        .iter()
        .find(|entry| entry.exists)
        .cloned()
        .or_else(|| backups.first().cloned());

    Ok(PostgresUpgradeBackupDiagnostics {
        folder_path: paths.upgrade_backups_dir,
        folder_exists,
        last_successful_backup,
        backups,
    })
}

#[tauri::command]
async fn restore_postgres_experiment_upgrade_backup_command(
    app: tauri::AppHandle,
    postgres_process: tauri::State<'_, BundledPostgresProcess>,
    runtime_auth_state: tauri::State<'_, PostgresExperimentAuthState>,
    request: RestorePostgresUpgradeBackupRequest,
) -> Result<RestorePostgresUpgradeBackupResult, String> {
    let backup_path = PathBuf::from(request.backup_path.trim());
    if !backup_path.is_file() {
        return Err("Choose a KanQual upgrade backup file.".to_string());
    }
    if request.backup_password.trim().is_empty() {
        return Err("Enter the password that protects the upgrade backup.".to_string());
    }
    if request.new_admin_password.trim().len() < 8 {
        return Err("Choose a new administrator password with at least 8 characters.".to_string());
    }

    let preflight = bundled_postgres::init_preflight(app.clone()).await?;
    if !preflight.can_initialize {
        return Err(format!(
            "Restore is only available before first launch on a fresh data directory: {}",
            preflight.issues.join(" ")
        ));
    }

    let encrypted = fs::read_to_string(&backup_path).map_err(|e| {
        format!(
            "Could not read upgrade backup at {}: {e}",
            backup_path.display()
        )
    })?;
    let plaintext = decrypt_encrypted_backup_payload_text(
        &encrypted,
        &request.backup_password,
        Some(ensure_upgrade_backup_json_shape),
    )?;
    let backup: Value = serde_json::from_str(&plaintext)
        .map_err(|_| "The decrypted upgrade backup is not valid JSON.".to_string())?;
    ensure_upgrade_backup_json_shape(&plaintext)?;

    let control_dump = backup
        .get("controlDump")
        .and_then(Value::as_object)
        .and_then(|object| object.get("sql"))
        .and_then(Value::as_str)
        .ok_or_else(|| "The upgrade backup is missing the control database dump.".to_string())?;
    let project_dumps = backup
        .get("projectDumps")
        .and_then(Value::as_array)
        .ok_or_else(|| "The upgrade backup is missing project database dumps.".to_string())?;
    let projects = backup
        .get("projects")
        .and_then(Value::as_array)
        .ok_or_else(|| "The upgrade backup is missing project metadata.".to_string())?;
    let storage_files = backup
        .get("projectStorageFiles")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();

    let mut identity = generate_postgres_bootstrap_identity();
    identity.host = POSTGRES_DEFAULT_HOST.to_string();
    identity.port = POSTGRES_DEFAULT_PORT;
    identity.temporary_superuser_password.clear();
    identity.bootstrap_applied = true;
    identity.admin_handoff_completed = true;
    if !is_valid_postgres_superuser_name(&identity.superuser_name) {
        return Err("Generated PostgreSQL administrator username is invalid.".to_string());
    }

    let _ = bundled_postgres::stop_runtime(app.clone(), &postgres_process.0).await;
    bundled_postgres::initialize_cluster(
        app.clone(),
        &identity.superuser_name,
        &request.new_admin_password,
    )
    .await?;
    let start_result = bundled_postgres::start_runtime(app.clone(), &postgres_process.0).await?;
    if !start_result.status.reachable {
        return Err(
            "KanQual restored the database files but could not start PostgreSQL.".to_string(),
        );
    }

    save_postgres_bootstrap_identity(&app, &identity)?;
    save_postgres_runtime_config(&app, &postgres_runtime_config_from_identity(&identity))?;
    set_postgres_runtime_auth_session(
        &runtime_auth_state,
        Some(StoredPostgresExperimentAuthSession {
            auth_kind: "postgres_admin".to_string(),
            user_id: "postgres_admin".to_string(),
            postgres_username: identity.superuser_name.clone(),
            postgres_password: request.new_admin_password.clone(),
            started_at_ms: current_time_ms(),
        }),
    );

    let paths = bundled_postgres::resolve_paths(&app)?;
    let psql_path = PathBuf::from(&paths.psql_binary);
    ensure_postgres_control_database(&identity, &psql_path, &request.new_admin_password)?;
    run_psql_script_with_binary(
        &psql_path,
        &identity.host,
        identity.port,
        &identity.superuser_name,
        &request.new_admin_password,
        &identity.app_database,
        control_dump,
    )
    .map_err(|e| format!("Could not restore KanQual control database: {e}"))?;

    for dump in project_dumps {
        let database_name = backup_value_string(dump, "databaseName");
        let sql = backup_value_string(dump, "sql");
        if database_name.trim().is_empty() || sql.trim().is_empty() {
            return Err("A project database dump in the backup is incomplete.".to_string());
        }
        let database_ident = sql_escape_identifier(&database_name);
        let admin_ident = sql_escape_identifier(&identity.superuser_name);
        run_psql_command_with_binary(
            &psql_path,
            &identity.host,
            identity.port,
            &identity.superuser_name,
            &request.new_admin_password,
            "postgres",
            &format!("CREATE DATABASE \"{database_ident}\" OWNER \"{admin_ident}\";"),
        )
        .map_err(|e| format!("Could not create restored project database {database_name}: {e}"))?;
        run_psql_script_with_binary(
            &psql_path,
            &identity.host,
            identity.port,
            &identity.superuser_name,
            &request.new_admin_password,
            &database_name,
            &sql,
        )
        .map_err(|e| format!("Could not restore project database {database_name}: {e}"))?;
    }

    ensure_postgres_experiment_control_schema(&app).await?;
    let (client, connection_task) = connect_postgres_runtime(&app).await?;
    client
        .execute(
            "UPDATE app_users SET must_change_password = TRUE, updated_at = NOW()",
            &[],
        )
        .await
        .map_err(|e| format!("Could not mark restored users for password reset: {e}"))?;
    let user_rows = client
        .query(
            "SELECT username FROM app_users ORDER BY lower(username) ASC",
            &[],
        )
        .await
        .map_err(|e| format!("Could not load restored users: {e}"))?;
    for row in &user_rows {
        let email: String = row.get(0);
        let temporary_password = generate_temporary_password();
        let _ = ensure_postgres_login_role_for_app_user(
            &identity,
            &psql_path,
            &identity.superuser_name,
            &request.new_admin_password,
            &email,
            &temporary_password,
        );
    }

    for project in projects {
        let project_id = backup_value_string(project, "id");
        if project_id.trim().is_empty() {
            continue;
        }
        let storage_path = postgres_project_storage_path(&app, &project_id)?;
        fs::create_dir_all(&storage_path).map_err(|e| {
            format!(
                "Could not create restored project storage folder at {}: {e}",
                storage_path.display()
            )
        })?;
        let storage_path_string = storage_path.to_string_lossy().to_string();
        client
            .execute(
                "UPDATE projects SET storage_path = $2, updated_at = NOW() WHERE id = $1",
                &[&project_id, &storage_path_string],
            )
            .await
            .map_err(|e| format!("Could not update restored project storage path: {e}"))?;
    }

    for file in &storage_files {
        let project_id = backup_value_string(file, "projectId");
        let relative_path = backup_value_string(file, "relativePath");
        let bytes_b64 = backup_value_string(file, "bytesB64");
        if project_id.trim().is_empty() || relative_path.trim().is_empty() {
            continue;
        }
        let root = postgres_project_storage_path(&app, &project_id)?;
        let safe_relative = safe_backup_relative_path(&relative_path)?;
        let target_path = root.join(safe_relative);
        if let Some(parent) = target_path.parent() {
            fs::create_dir_all(parent)
                .map_err(|e| format!("Could not create restored storage folder: {e}"))?;
        }
        let bytes = BASE64_STANDARD
            .decode(bytes_b64)
            .map_err(|_| "A restored storage file is not valid base64.".to_string())?;
        fs::write(&target_path, bytes)
            .map_err(|e| format!("Could not write restored storage file: {e}"))?;
    }

    connection_task.abort();
    for project in projects {
        let database_name = backup_value_string(project, "databaseName");
        if !database_name.trim().is_empty() {
            let _ = ensure_postgres_experiment_project_schema(&app, &database_name).await;
            if let Ok((project_client, project_connection_task)) =
                connect_postgres_database(&app, &database_name).await
            {
                if let Ok(rows) = project_client
                    .query(
                        "SELECT email FROM project_users ORDER BY lower(email) ASC",
                        &[],
                    )
                    .await
                {
                    for row in rows {
                        let email: String = row.get(0);
                        let _ = grant_postgres_project_database_access_for_role(
                            &app,
                            &database_name,
                            &email,
                        )
                        .await;
                    }
                }
                project_connection_task.abort();
            }
        }
    }

    set_postgres_runtime_auth_session(&runtime_auth_state, None);

    Ok(RestorePostgresUpgradeBackupResult {
        restored_at_ms: current_time_ms(),
        kanqual_version: env!("CARGO_PKG_VERSION").to_string(),
        backup_kanqual_version: backup_value_string(&backup, "kanqualVersion"),
        backup_postgres_version: backup_value_string(&backup, "postgresVersion"),
        project_count: projects.len(),
        storage_file_count: storage_files.len(),
        user_count: user_rows.len(),
    })
}

