fn ollama_base_url(protocol: &str, host: &str, port: u16) -> String {
    format!(
        "{}://{}:{}",
        if protocol.eq_ignore_ascii_case("https") {
            "https"
        } else {
            "http"
        },
        host.trim().trim_end_matches('/'),
        port,
    )
}

